// Git branches (worktrees) + preview keys + port allocation. Git itself runs in claudebox (/v2/git/*).
import crypto from 'node:crypto';
import path from 'node:path';
import type { ProjectRow } from '../auth.js';
import { ClaudeboxError } from '../claudebox.js';
import type { Config } from '../config.js';
import type { Ctx } from '../ctx.js';
import type { DB } from '../db.js';
import { iso } from '../db.js';
import { badRequest, conflict, HttpError, notFound } from './errors.js';

/** Lowercase segments joined by single '-' or '/'. Never contains '--' (the preview-key separator). */
export const BRANCH_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*(?:\/[a-z0-9]+(?:-[a-z0-9]+)*)*$/;
export const BRANCH_MAX = 40;
const RESERVED = new Set(['main', 'master', 'head']);

export interface BranchRow {
  id: string;
  project_id: string;
  name: string;
  dir: string;
  base: string;
  preview_port: number;
  status: 'active' | 'merged' | 'discarded';
  created_by: string | null;
  created_at: number;
  closed_at: number | null;
  merged_sha: string | null;
  files_changed: number | null;
  ahead: number | null;
  behind: number | null;
  stat_at: number | null;
}

export function validBranchName(name: string, project?: Pick<ProjectRow, 'git_main'>): string | null {
  if (!name || name.length > BRANCH_MAX) return `Branch names are 1-${BRANCH_MAX} characters`;
  if (!BRANCH_RE.test(name)) return 'Use lowercase letters, digits, single dashes and "/" (e.g. feature/login)';
  if (RESERVED.has(name) || name === project?.git_main) return `"${name}" is reserved`;
  return null;
}

/** Worktree directory name (stable for the branch's lifetime): '/' → '_'. */
export function worktreeDirName(name: string): string {
  return name.replace(/\//g, '_').slice(0, 64);
}

/** Preview key used in /preview/<key>/ and BASE_PATH: <slug> for main, <slug>--<dir> for branches. */
export function previewKey(slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return b ? `${slug}--${b.dir}` : slug;
}
export function previewPath(slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return `/preview/${previewKey(slug, b)}/`;
}

export function worktreePath(cfg: Config, slug: string, dir: string): string {
  return path.join(cfg.projectsDir, '.branches', slug, dir);
}
export function branchesRoot(cfg: Config, slug: string): string {
  return path.join(cfg.projectsDir, '.branches', slug);
}
/** cwd as seen by Claude inside claudebox. */
export function claudeboxCwd(cfg: Config, slug: string, b?: Pick<BranchRow, 'dir'> | null): string {
  return b ? `${cfg.claudeboxProjectsDir}/.branches/${slug}/${b.dir}` : `${cfg.claudeboxProjectsDir}/${slug}`;
}

export function getBranch(db: DB, projectId: string, name: string): BranchRow | null {
  return (db.prepare(`SELECT * FROM branches WHERE project_id = ? AND name = ? AND status = 'active'`).get(projectId, name) as BranchRow | undefined) ?? null;
}
export function activeBranches(db: DB, projectId: string): BranchRow[] {
  return db.prepare(`SELECT * FROM branches WHERE project_id = ? AND status = 'active' ORDER BY created_at`).all(projectId) as BranchRow[];
}

/** `?branch=` → active branch row, or null for main ('' / 'main' / the repo's main branch name). 404 if unknown. */
export function branchParam(db: DB, project: ProjectRow, raw: unknown): BranchRow | null {
  if (raw == null || raw === '' || raw === 'main' || (typeof raw === 'string' && raw === project.git_main)) return null;
  if (typeof raw !== 'string' || raw.length > 100) throw badRequest('Invalid branch');
  const b = getBranch(db, project.id, raw);
  if (!b) throw notFound(`Branch "${raw}" not found`);
  return b;
}

/** Active (queued/running) runs on main (branch = null) or a branch of a project. */
export function activeRunCount(db: DB, projectId: string, branch: string | null): number {
  return (db
    .prepare(`SELECT COUNT(*) AS n FROM runs WHERE project_id = ? AND status IN ('queued','running') AND branch IS ?`)
    .get(projectId, branch) as { n: number }).n;
}

export function allocatePort(ctx: Pick<Ctx, 'db' | 'cfg'>): number {
  const used = new Set<number>([
    ...(ctx.db.prepare(`SELECT preview_port AS p FROM projects`).all() as { p: number }[]).map((r) => r.p),
    ...(ctx.db.prepare(`SELECT preview_port AS p FROM branches WHERE status = 'active'`).all() as { p: number }[]).map((r) => r.p),
  ]);
  for (let p = ctx.cfg.previewPortMin; p <= ctx.cfg.previewPortMax; p++) if (!used.has(p)) return p;
  throw conflict('No free preview ports left (all 100 are allocated). Delete a project or close a branch first.', 'no_ports');
}

export function branchDTO(b: BranchRow, project: Pick<ProjectRow, 'slug'>, live?: { ahead?: number; behind?: number; filesChanged?: number; dirty?: boolean } | null) {
  return {
    id: b.id,
    name: b.name,
    base: b.base,
    status: b.status,
    previewPort: b.preview_port,
    previewPath: previewPath(project.slug, b),
    createdBy: b.created_by,
    createdAt: iso(b.created_at)!,
    closedAt: iso(b.closed_at),
    mergedSha: b.merged_sha,
    ahead: live?.ahead ?? b.ahead,
    behind: live?.behind ?? b.behind,
    filesChanged: live?.filesChanged ?? b.files_changed,
    dirty: live?.dirty ?? null,
  };
}

/** Map a claudebox git error onto an HttpError (keeps 4xx semantics). */
export function gitError(err: unknown): HttpError {
  if (err instanceof HttpError) return err;
  if (err instanceof ClaudeboxError) {
    const body = (err.body ?? {}) as { code?: string };
    if (err.statusCode === 404) return new HttpError(404, body.code ?? 'git_not_found', err.message);
    if (err.statusCode === 409) return new HttpError(409, body.code ?? 'git_conflict', err.message);
    if (err.statusCode === 400) return new HttpError(400, body.code ?? 'git_invalid', err.message);
    return new HttpError(502, 'git_failed', err.message);
  }
  return new HttpError(502, 'git_failed', (err as Error)?.message ?? 'git failed');
}

// ---------- repo bootstrap ----------
const ensured = new Map<string, Promise<string>>();

/** Make sure the project's directory is a git repo (init / adopt, lazily). Returns the main branch name. */
export function ensureGit(ctx: Pick<Ctx, 'db' | 'cb' | 'log'>, project: Pick<ProjectRow, 'id' | 'slug' | 'git_main'>): Promise<string> {
  let p = ensured.get(project.id);
  if (!p) {
    p = (async () => {
      // Sandbox first (claudebox SANDBOX_MODE=strict): dir ownership/ACLs, home, one-time session migration.
      const sb = await ctx.cb.sandboxSetup(project.slug);
      if (sb?.heavy) ctx.log.info({ project: project.slug }, 'project sandbox set up');
      const r = await ctx.cb.git<{ mainBranch: string; initialized: boolean; adopted: boolean }>('ensure', { projectSlug: project.slug });
      if (r.mainBranch !== project.git_main) ctx.db.prepare(`UPDATE projects SET git_main = ? WHERE id = ?`).run(r.mainBranch, project.id);
      project.git_main = r.mainBranch;
      if (r.initialized) ctx.log.info({ project: project.slug, main: r.mainBranch, adopted: r.adopted }, 'git repo initialized');
      return r.mainBranch;
    })();
    ensured.set(project.id, p);
    p.catch(() => ensured.delete(project.id));
  }
  return p.catch((err) => {
    throw gitError(err);
  });
}
export function forgetGit(projectId: string) {
  ensured.delete(projectId);
}

/** Background: init/adopt every project's repo at startup (retries while claudebox comes up). */
export async function ensureAllRepos(ctx: Pick<Ctx, 'db' | 'cb' | 'log'>, isClosed: () => boolean) {
  for (let attempt = 0; attempt < 30 && !isClosed(); attempt++) {
    const projects = ctx.db.prepare(`SELECT id, slug, git_main FROM projects WHERE archived = 0`).all() as Pick<ProjectRow, 'id' | 'slug' | 'git_main'>[];
    let failed = 0;
    for (const p of projects) {
      if (isClosed()) return;
      try {
        await ensureGit(ctx, p);
      } catch (err) {
        failed++;
        if (attempt === 0) ctx.log.warn({ project: p.slug, err: (err as Error).message }, 'git ensure failed (will retry)');
      }
    }
    if (!failed) return;
    await new Promise((r) => setTimeout(r, Math.min(60_000, 3000 * (attempt + 1))).unref?.());
  }
}

export const newBranchId = () => crypto.randomUUID();

/**
 * Commit pending edits (e.g. made in the editor) right before a run starts, so the run's own
 * auto-checkpoint contains only the run's changes and "Undo this run" never reverts user edits.
 * Best effort: never blocks a run for long or fails it.
 */
export async function preRunCheckpoint(ctx: Pick<Ctx, 'db' | 'cb' | 'log'>, project: ProjectRow, b: BranchRow | null) {
  try {
    const main = await ensureGit(ctx, project);
    await ctx.cb.git('checkpoint', {
      projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), message: 'nxeon: edits before run', expectBranch: b ? b.name : main,
    }, 8000);
  } catch (err) {
    ctx.log.warn({ err: (err as Error).message, project: project.slug }, 'pre-run checkpoint failed');
  }
}
import { request } from 'undici';
import type { Config } from './config.js';
import type { SandboxSpec } from './lib/sandbox.js';

export interface V2RunBody {
  runId: string;
  prompt: string;
  projectSlug: string;
  sessionId: string | null;
  model: string;
  mode: string;
  thinking: string;
  attachments: string[];
  appendSystemPrompt: string;
  maxTurns: number;
  previewPort: number;
  /** Branch runs: worktree dir under .branches/<slug>/ (cwd + preview key <slug>--<worktree>). */
  worktree?: string;
  authToken?: string;
  /** Context size at which to auto-compact (0/absent = CLI default). */
  autocompactTokens?: number;
  /** Custom subagents → `--agents`. */
  agents?: Record<string, { description: string; prompt: string; tools?: string[]; model?: string }>;
  /** Lead agent → `--agent` (must be a key of `agents`). */
  agent?: string;
  /** Sandbox identity (claudebox SANDBOX_MODE=strict). Attached automatically from projectSlug when absent. */
  sandbox?: SandboxSpec;
  /** Multi-project runs only: cwd under /workspace/.nexus (requires `sandbox`) + project dirs for --add-dir. */
  cwd?: string;
  addDirs?: string[];
}

export interface PreviewStatusUpstream {
  projectSlug?: string;
  running: boolean;
  managed?: boolean;
  listening?: boolean;
  port: number | null;
  pid?: number | null;
  kind?: string | null;
  command?: string | null;
  startedAt?: number | null;
  exitCode?: number | null;
  logTail?: string[] | string;
}

export class ClaudeboxError extends Error {
  constructor(public statusCode: number, message: string, public body: unknown = null) {
    super(message);
  }
}

export class Claudebox {
  /** Project slug → sandbox spec (set by the app from the DB); attached to every project-scoped call. */
  sandboxFor: (projectSlug: string) => SandboxSpec | null = () => null;

  constructor(private cfg: Config) {}

  private withSandbox<T extends Record<string, unknown>>(body: T): T {
    if (body.sandbox !== undefined || typeof body.projectSlug !== 'string') return body;
    const sandbox = this.sandboxFor(body.projectSlug);
    return sandbox ? { ...body, sandbox } : body;
  }

  private headers(extra: Record<string, string> = {}) {
    return {
      authorization: `Bearer ${this.cfg.claudeboxApiKey}`,
      ...extra,
    };
  }

  /** Start a run; returns the raw undici response (SSE body). */
  startRun(body: V2RunBody, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run`, {
      method: 'POST',
      headers: this.headers({ 'content-type': 'application/json', accept: 'text/event-stream' }),
      body: JSON.stringify(this.withSandbox(body as unknown as Record<string, unknown>)),
      signal,
      headersTimeout: 60_000,
      bodyTimeout: 0,
    });
  }

  /** Re-attach to a run's buffered event stream. */
  attach(runId: string, fromSeq: number, signal: AbortSignal) {
    return request(`${this.cfg.claudeboxUrl}/v2/run/${encodeURIComponent(runId)}/events?fromSeq=${fromSeq}`, {
      method: 'GET',
      headers: this.headers({ accept: 'text/event-stream' }),
      signal,
      headersTimeout: 30_000,
      bodyTimeout: 0,
    });
  }

  private async json<T>(method: 'GET' | 'POST', path: string, body?: unknown, timeoutMs = 15_000): Promise<T> {
    const res = await request(`${this.cfg.claudeboxUrl}${path}`, {
      method,
      headers: this.headers(body !== undefined ? { 'content-type': 'application/json' } : {}),
      body: body !== undefined ? JSON.stringify(body) : undefined,
      headersTimeout: timeoutMs,
      bodyTimeout: timeoutMs,
    });
    const text = await res.body.text();
    let data: unknown = text;
    try {
      data = JSON.parse(text);
    } catch {
      /* not json */
    }
    if (res.statusCode >= 400) {
      const msg =
        (data as { error?: string | { message?: string } })?.error ?? (typeof data === 'string' ? data : `HTTP ${res.statusCode}`);
      throw new ClaudeboxError(res.statusCode, typeof msg === 'string' ? msg : msg?.message ?? `HTTP ${res.statusCode}`, data);
    }
    return data as T;
  }

  abort(runId: string) {
    return this.json<unknown>('POST', '/v2/abort', { runId });
  }
  previewStart(projectSlug: string, port: number, command?: string | null, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'POST', '/v2/preview/start', this.withSandbox({ projectSlug, port, ...(command ? { command } : {}), ...(worktree ? { worktree } : {}) }), 120_000,
    );
  }
  previewStop(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream & { stopped?: boolean }>('POST', '/v2/preview/stop', this.withSandbox({
      projectSlug, ...(port ? { port } : {}), ...(worktree ? { worktree } : {}),
    }));
  }
  previewStatus(projectSlug: string, port?: number, worktree?: string | null) {
    return this.json<PreviewStatusUpstream>(
      'GET',
      `/v2/preview/status?projectSlug=${encodeURIComponent(projectSlug)}${port ? `&port=${port}` : ''}${worktree ? `&worktree=${encodeURIComponent(worktree)}` : ''}`,
    );
  }
  previews(timeoutMs = 2000) {
    return this.json<{ previews: PreviewStatusUpstream[] }>('GET', '/v2/previews', undefined, timeoutMs);
  }
  /** POST /v2/git/<op> (see claudebox/lib/git.js). */
  git<T = Record<string, unknown>>(op: string, body: Record<string, unknown>, timeoutMs = 130_000) {
    return this.json<T>('POST', `/v2/git/${op}`, this.withSandbox(body), timeoutMs);
  }
  /** Create/repair a project's sandbox (dir ownership + ACLs, home, one-time session migration). Idempotent. */
  sandboxSetup(projectSlug: string, force = false) {
    return this.json<{ ok?: boolean; heavy?: boolean; skipped?: boolean; mode?: string }>(
      'POST', '/v2/sandbox/setup', this.withSandbox({ projectSlug, ...(force ? { force: true } : {}) }), 600_000,
    );
  }
  health() {
    return this.json<Record<string, unknown>>('GET', '/health', undefined, 5000);
  }
}

import type { WebSocket } from 'ws';
import type { DB } from './db.js';
import { projectRole, type UserRow } from './auth.js';
import type { ServerMsg } from './shared/protocol.js';

const MAX_BUFFERED = 8 * 1024 * 1024; // close slow consumers (they reconnect + replay)

export interface Client {
  ws: WebSocket;
  user: Pick<UserRow, 'id' | 'role' | 'email'>;
  runs: Set<string>;
  projects: Set<string>;
  /** watched checkouts: watchKey(projectId, branch) */
  watches: Set<string>;
  /** cache of view permission per project (ms timestamp of check, allowed) */
  viewCache: Map<string, { at: number; ok: boolean }>;
  alive: boolean;
}

export const watchKey = (projectId: string, branch: string | null) => `${projectId}\u0001${branch ?? ''}`;
export function parseWatchKey(k: string): { projectId: string; branch: string | null } {
  const i = k.indexOf('\u0001');
  return { projectId: k.slice(0, i), branch: k.slice(i + 1) || null };
}

export class Hub {
  clients = new Set<Client>();
  private runSubs = new Map<string, Set<Client>>();
  private projectSubs = new Map<string, Set<Client>>();
  private watchSubs = new Map<string, Set<Client>>();
  /** called when a checkout (main = branch null) gains its first / loses its last watcher */
  onWatchChange: (projectId: string, branch: string | null, subscribed: boolean) => void = () => {};

  constructor(private db: DB) {}

  add(c: Client) {
    this.clients.add(c);
  }

  remove(c: Client) {
    this.clients.delete(c);
    for (const r of c.runs) this.unsubRun(c, r);
    for (const p of [...c.projects]) this.unsubProject(c, p);
  }

  send(c: Client, msg: ServerMsg | string) {
    const ws = c.ws;
    if (ws.readyState !== ws.OPEN) return;
    if (ws.bufferedAmount > MAX_BUFFERED) {
      ws.close(1013, 'slow consumer');
      return;
    }
    ws.send(typeof msg === 'string' ? msg : JSON.stringify(msg));
  }

  subRun(c: Client, runId: string) {
    c.runs.add(runId);
    let s = this.runSubs.get(runId);
    if (!s) this.runSubs.set(runId, (s = new Set()));
    s.add(c);
  }
  unsubRun(c: Client, runId: string) {
    c.runs.delete(runId);
    const s = this.runSubs.get(runId);
    if (s) {
      s.delete(c);
      if (!s.size) this.runSubs.delete(runId);
    }
  }

  subProject(c: Client, projectId: string, branch: string | null = null) {
    if (!c.projects.has(projectId)) {
      c.projects.add(projectId);
      let s = this.projectSubs.get(projectId);
      if (!s) this.projectSubs.set(projectId, (s = new Set()));
      s.add(c);
    }
    const key = watchKey(projectId, branch);
    if (c.watches.has(key)) return;
    c.watches.add(key);
    let w = this.watchSubs.get(key);
    if (!w) this.watchSubs.set(key, (w = new Set()));
    w.add(c);
    if (w.size === 1) this.onWatchChange(projectId, branch, true);
  }
  /** branch undefined = drop every subscription of this client to the project. */
  unsubProject(c: Client, projectId: string, branch?: string | null) {
    const keys = branch === undefined ? [...c.watches].filter((k) => parseWatchKey(k).projectId === projectId) : [watchKey(projectId, branch)];
    for (const key of keys) {
      if (!c.watches.delete(key)) continue;
      const w = this.watchSubs.get(key);
      if (!w) continue;
      w.delete(c);
      if (!w.size) {
        this.watchSubs.delete(key);
        const k = parseWatchKey(key);
        this.onWatchChange(k.projectId, k.branch, false);
      }
    }
    if ([...c.watches].some((k) => parseWatchKey(k).projectId === projectId)) return;
    if (!c.projects.delete(projectId)) return;
    const s = this.projectSubs.get(projectId);
    if (s) {
      s.delete(c);
      if (!s.size) this.projectSubs.delete(projectId);
    }
  }

  hasProjectSubscribers(projectId: string) {
    return (this.projectSubs.get(projectId)?.size ?? 0) > 0;
  }

  broadcastRun(runId: string, msg: ServerMsg) {
    const s = this.runSubs.get(runId);
    if (!s) return;
    const payload = JSON.stringify(msg);
    for (const c of s) this.send(c, payload);
  }

  broadcastProject(projectId: string, msg: ServerMsg) {
    const s = this.projectSubs.get(projectId);
    if (!s) return;
    const payload = JSON.stringify(msg);
    for (const c of s) this.send(c, payload);
  }

  canView(c: Client, projectId: string): boolean {
    if (c.user.role === 'admin') return true;
    const cached = c.viewCache.get(projectId);
    const t = Date.now();
    if (cached && t - cached.at < 30_000) return cached.ok;
    const ok = !!projectRole(this.db, c.user, projectId);
    c.viewCache.set(projectId, { at: t, ok });
    return ok;
  }

  /** Everyone connected who may view the project (graph pulses + run status for the Nexus view). */
  broadcastViewers(projectId: string, msg: ServerMsg) {
    const payload = JSON.stringify(msg);
    for (const c of this.clients) if (this.canView(c, projectId)) this.send(c, payload);
  }

  /** Drop all sockets of a user (disabled / deleted / logged out everywhere). */
  kickUser(userId: string) {
    for (const c of this.clients) if (c.user.id === userId) c.ws.close(4401, 'session ended');
  }

  invalidatePermissions() {
    for (const c of this.clients) c.viewCache.clear();
  }
}
import type { FastifyInstance } from 'fastify';
import type http from 'node:http';
import type { Duplex } from 'node:stream';
import { WebSocketServer, type WebSocket } from 'ws';
import { projectRole, SESSION_COOKIE } from '../auth.js';
import type { Ctx } from '../ctx.js';
import { parseJson } from '../db.js';
import type { Client } from '../hub.js';
import type { ClientMsg, RunStatus, Suggestion } from '../shared/protocol.js';
import { clientIpOf, handlePreviewUpgrade } from './previewProxy.js';

export function attachWebSocket(app: FastifyInstance, ctx: Ctx) {
  const wss = new WebSocketServer({ noServer: true, maxPayload: 64 * 1024, perMessageDeflate: false });
  const { hub, db, runs } = ctx;

  const reject = (socket: Duplex, code: number, text: string) => {
    socket.end(`HTTP/1.1 ${code} ${text}\r\nConnection: close\r\nContent-Length: 0\r\n\r\n`);
  };

  app.server.on('upgrade', (req: http.IncomingMessage, socket: Duplex, head: Buffer) => {
    socket.on('error', () => socket.destroy());
    const url = req.url ?? '';
    if (url.startsWith('/preview/')) {
      handlePreviewUpgrade(app, ctx, req, socket, head);
      return;
    }
    if (url !== '/ws' && !url.startsWith('/ws?')) return reject(socket, 404, 'Not Found');
    const ip = clientIpOf(ctx, req);
    if (!ctx.ipRules.isAllowed(ip)) return reject(socket, 403, 'Forbidden');
    const origin = req.headers.origin;
    if (origin && !originOk(origin, req, ctx)) return reject(socket, 403, 'Forbidden');
    const token = app.parseCookie(req.headers.cookie ?? '')[SESSION_COOKIE];
    const user = ctx.sessions.lookup(token);
    if (!user) return reject(socket, 401, 'Unauthorized');
    wss.handleUpgrade(req, socket, head, (ws) => onConnection(ws, { id: user.id, role: user.role, email: user.email }, token!));
  });

  function onConnection(ws: WebSocket, user: Client['user'], token: string) {
    const c: Client = { ws, user, runs: new Set(), projects: new Set(), watches: new Set(), viewCache: new Map(), alive: true };
    hub.add(c);
    ws.on('pong', () => (c.alive = true));
    ws.on('close', () => hub.remove(c));
    ws.on('error', () => ws.terminate());
    ws.on('message', (raw, isBinary) => {
      if (isBinary) return;
      let msg: ClientMsg;
      try {
        msg = JSON.parse(raw.toString()) as ClientMsg;
      } catch {
        return hub.send(c, { t: 'error', message: 'invalid json' });
      }
      try {
        handle(c, msg);
      } catch (err) {
        ctx.log.warn({ err: (err as Error).message }, 'ws message failed');
        hub.send(c, { t: 'error', message: 'internal error' });
      }
    });
    // periodic session re-validation (logout / disable / password change)
    const recheck = setInterval(() => {
      const u = ctx.sessions.lookup(token);
      if (!u) ws.close(4401, 'session ended');
      else c.user = { id: u.id, role: u.role, email: u.email };
    }, 60_000);
    ws.on('close', () => clearInterval(recheck));
  }

  function handle(c: Client, msg: ClientMsg) {
    switch (msg?.t) {
      case 'ping':
        return hub.send(c, { t: 'pong' });
      case 'sub': {
        if (typeof msg.runId !== 'string') return;
        const run = db.prepare(`SELECT id, project_id, conversation_id, status FROM runs WHERE id = ?`).get(msg.runId) as
          | { id: string; project_id: string; conversation_id: string; status: RunStatus }
          | undefined;
        if (!run || !projectRole(db, c.user, run.project_id)) return hub.send(c, { t: 'error', message: `run ${msg.runId} not found` });
        const from = Number.isFinite(msg.fromSeq) ? Math.max(0, Math.floor(msg.fromSeq!)) : 0;
        // replay + subscribe synchronously: no events can slip in between
        const events = runs.replay(run.id, from);
        for (const e of events) hub.send(c, JSON.stringify({ t: 'run_event', runId: run.id, seq: e.seq, type: e.type, data: e.data, ts: e.ts }));
        hub.subRun(c, run.id);
        if (!runs.isActive(run.id)) {
          const fresh = db.prepare(`SELECT status FROM runs WHERE id = ?`).get(run.id) as { status: RunStatus };
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: fresh.status });
          const m = db.prepare(`SELECT suggestions FROM messages WHERE run_id = ? AND role = 'assistant'`).get(run.id) as
            | { suggestions: string | null }
            | undefined;
          const items = parseJson<Suggestion[]>(m?.suggestions, []);
          if (items.length) hub.send(c, { t: 'suggestions', runId: run.id, items });
        } else {
          hub.send(c, { t: 'run_status', runId: run.id, conversationId: run.conversation_id, projectId: run.project_id, status: 'running' });
        }
        return;
      }
      case 'unsub':
        if (typeof msg.runId === 'string') hub.unsubRun(c, msg.runId);
        return;
      case 'sub_project': {
        if (typeof msg.projectId !== 'string') return;
        if (!projectRole(db, c.user, msg.projectId)) return hub.send(c, { t: 'error', message: `project ${msg.projectId} not found` });
        const branch = typeof msg.branch === 'string' && msg.branch.length <= 100 ? msg.branch : null;
        hub.subProject(c, msg.projectId, branch);
        return;
      }
      case 'unsub_project':
        if (typeof msg.projectId === 'string') hub.unsubProject(c, msg.projectId, typeof msg.branch === 'string' ? msg.branch : msg.branch === null ? null : undefined);
        return;
      default:
        hub.send(c, { t: 'error', message: 'unknown message' });
    }
  }

  const heartbeat = setInterval(() => {
    for (const c of hub.clients) {
      if (!c.alive) {
        c.ws.terminate();
        continue;
      }
      c.alive = false;
      try {
        c.ws.ping();
      } catch {
        /* closed */
      }
    }
  }, 30_000);
  heartbeat.unref();
  app.addHook('onClose', async () => {
    clearInterval(heartbeat);
    wss.close();
  });
}

function originOk(origin: string, req: http.IncomingMessage, ctx: Ctx): boolean {
  try {
    const o = new URL(origin);
    if (o.origin === new URL(ctx.cfg.publicUrl).origin) return true;
    const host = (req.headers['x-forwarded-host'] as string | undefined) ?? req.headers.host;
    return !!host && o.host === host;
  } catch {
    return false;
  }
}
