}

export const hashPassword = (pw: string) => argon2.hash(pw, { type: argon2.argon2id });
export async function verifyPassword(hash: string, pw: string): Promise<boolean> {
  try {
    return await argon2.verify(hash, pw);
  } catch {
    return false;
  }
}
/** Constant-ish time dummy verify so unknown emails take as long as wrong passwords. */
let dummyHash: Promise<string> | null = null;
export async function dummyVerify(pw: string) {
  dummyHash ??= hashPassword('dummy-password-for-timing');
  await verifyPassword(await dummyHash, pw);
}

export class Sessions {
  constructor(
    private db: DB,
    private secret: string,
  ) {}

  private hashToken(token: string) {
    return crypto.createHmac('sha256', this.secret).update(token).digest('hex');
  }

  create(userId: string, ip: string, ua: string | undefined): string {
    const token = crypto.randomBytes(32).toString('base64url');
    const t = now();
    this.db
      .prepare(`INSERT INTO sessions(id, user_id, created_at, expires_at, last_seen_at, ip, user_agent) VALUES (?,?,?,?,?,?,?)`)
      .run(this.hashToken(token), userId, t, t + SESSION_TTL_MS, t, ip, (ua ?? '').slice(0, 300));
    return token;
  }

  /** Validate a token; slides expiry (at most once per minute). Returns the active user or null. */
  lookup(token: string | undefined | null): UserRow | null {
    if (!token || token.length > 100) return null;
    const id = this.hashToken(token);
    const row = this.db
      .prepare(
        `SELECT s.expires_at, s.last_seen_at, u.* FROM sessions s JOIN users u ON u.id = s.user_id WHERE s.id = ?`,
      )
      .get(id) as (UserRow & { expires_at: number; last_seen_at: number }) | undefined;
    if (!row) return null;
    const t = now();
    if (row.expires_at < t || row.disabled) {
      if (row.expires_at < t) this.db.prepare(`DELETE FROM sessions WHERE id = ?`).run(id);
      return null;
    }
    if (t - row.last_seen_at > 60_000) {
      this.db.prepare(`UPDATE sessions SET last_seen_at = ?, expires_at = ? WHERE id = ?`).run(t, t + SESSION_TTL_MS, id);
      this.db.prepare(`UPDATE users SET last_seen_at = ? WHERE id = ?`).run(t, row.id);
    }
    return row;
  }

  destroy(token: string | undefined) {
    if (token) this.db.prepare(`DELETE FROM sessions WHERE id = ?`).run(this.hashToken(token));
  }

  destroyAllForUser(userId: string, exceptToken?: string) {
    if (exceptToken) this.db.prepare(`DELETE FROM sessions WHERE user_id = ? AND id != ?`).run(userId, this.hashToken(exceptToken));
    else this.db.prepare(`DELETE FROM sessions WHERE user_id = ?`).run(userId);
  }

  purgeExpired() {
    this.db.prepare(`DELETE FROM sessions WHERE expires_at < ?`).run(now());
  }
}

// ---------- permissions ----------
export type EffectiveRole = ProjectRole | 'admin';
const RANK: Record<EffectiveRole, number> = { viewer: 1, editor: 2, owner: 3, admin: 4 };

/**
 * Effective role on a project. Sub-projects inherit their parent's members: effective = max(own, parent's).
 * Admins see everything.
 */
export function projectRole(db: DB, user: Pick<UserRow, 'id' | 'role'>, projectId: string): EffectiveRole | null {
  if (user.role === 'admin') return 'admin';
  const r = db
    .prepare(
      `SELECT (SELECT role FROM project_members WHERE project_id = p.id AND user_id = ?) AS own,
              (SELECT role FROM project_members WHERE project_id = p.parent_id AND user_id = ?) AS inherited
       FROM projects p WHERE p.id = ?`,
    )
    .get(user.id, user.id, projectId) as { own: ProjectRole | null; inherited: ProjectRole | null } | undefined;
  return maxRole(r?.own ?? null, r?.inherited ?? null);
}

export function maxRole(a: EffectiveRole | null, b: EffectiveRole | null): EffectiveRole | null {
  if (!a) return b;
  if (!b) return a;
  return RANK[a] >= RANK[b] ? a : b;
}

export function hasRole(role: EffectiveRole | null, min: ProjectRole): boolean {
  return !!role && RANK[role] >= RANK[min];
}

export interface ProjectRow {
  id: string;
  slug: string;
  name: string;
  description: string;
  color: string;
  icon: string;
  preview_port: number;
  preview_command: string | null;
  preview_strip: number;
  links: string;
  created_by: string | null;
  created_at: number;
  last_active_at: number | null;
  archived: number;
  parent_id: string | null;
  git_main: string | null;
  /** sandbox uid/gid = 20000 + sandbox_id (see lib/sandbox.ts) */
  sandbox_id: number | null;
}

/** Load a project and check the user's permission. Non-members get 404 (don't leak existence). */
export function requireProject(db: DB, user: UserRow, projectId: string, min: ProjectRole): { project: ProjectRow; role: EffectiveRole } {
  const project = db.prepare(`SELECT * FROM projects WHERE id = ?`).get(projectId) as ProjectRow | undefined;
  if (!project) throw notFound('Project not found');
  const role = projectRole(db, user, project.id);
  if (!role) throw notFound('Project not found');
  if (!hasRole(role, min)) throw forbidden(`Requires ${min} permission on this project`);
  return { project, role };
}

// ---------- request helpers ----------
declare module 'fastify' {
  interface FastifyRequest {
    user: UserRow | null;
    clientIp: string;
  }
}

export function requireUser(req: FastifyRequest): UserRow {
  if (!req.user) throw unauthorized();
  return req.user;
}

