_prepareSandboxed(run) {
  const c = this.config;
  const opts = run.opts;
  const spec = opts.sandbox;
  const home = spec.home;
  const runDir = path.join(home, ".nxeon", "runs", run.runId.replace(/[^A-Za-z0-9._-]/g, "_"));
  fs.mkdirSync(runDir, { recursive: true });
  run.runDir = runDir;
  const upDir = path.join(home, "uploads");
  fs.mkdirSync(upDir, { recursive: true });
  const attachments = [];
  for (const a of opts.attachments) {
    if (c.uploadsDir && isInside(a, c.uploadsDir)) {
      const rel = path.relative(c.uploadsDir, a);
      const dest = path.join(upDir, rel);
      if (!fs.existsSync(dest)) {
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        copyIntoSandbox(a, dest);
      }
      attachments.push(dest);
    } else attachments.push(a);
  }
  opts.fullPrompt = buildPrompt(opts.prompt, attachments);
  opts.promptViaStdin = true;
  opts.addDirsResolved = [upDir, ...(opts.addDirs || [])];
  if (opts.appendSystemPrompt) {
    opts.appendSystemPromptFile = path.join(runDir, "system-prompt.md");
    fs.writeFileSync(opts.appendSystemPromptFile, opts.appendSystemPrompt, { mode: 0o640 });
  }
  if (opts.agents) {
    opts.agentsFile = path.join(runDir, "agents.json");
    fs.writeFileSync(opts.agentsFile, JSON.stringify(opts.agents), { mode: 0o640 });
