/** Projects visible to the user (admins: all). Members of a parent also see its sub-projects (inherited role). */
export function visibleProjects(ctx: Ctx, user: UserRow, includeArchived: boolean): { p: ProjectRow; role: EffectiveRole }[] {
  const arch = includeArchived ? '' : 'AND p.archived = 0';
  if (user.role === 'admin') {
    return (ctx.db.prepare(`SELECT p.* FROM projects p WHERE 1=1 ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`).all() as ProjectRow[]).map(
      (p) => ({ p, role: 'admin' as const }),
    );
  }
  return (
    ctx.db
      .prepare(
        `SELECT p.*, m.role AS member_role, pm.role AS parent_role FROM projects p
         LEFT JOIN project_members m ON m.project_id = p.id AND m.user_id = ?
         LEFT JOIN project_members pm ON p.parent_id IS NOT NULL AND pm.project_id = p.parent_id AND pm.user_id = ?
         WHERE (m.role IS NOT NULL OR pm.role IS NOT NULL) ${arch} ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`,
      )
      .all(user.id, user.id) as (ProjectRow & { member_role: ProjectRole | null; parent_role: ProjectRole | null })[]
  ).map((p) => ({ p, role: maxRole(p.member_role, p.parent_role)! }));
}

/** Background: refresh cached ahead/behind/changed-files of branches whose stats are older than a minute. */
const statsInFlight = new Set<string>();
function refreshBranchStats(ctx: Ctx, rows: BranchRow[], projects: Map<string, ProjectRow>) {
  const stale = new Map<string, BranchRow[]>();
  for (const b of rows) {
    if (b.stat_at && now() - b.stat_at < 60_000) continue;
    if (statsInFlight.has(b.project_id)) continue;
    const arr = stale.get(b.project_id) ?? [];
    arr.push(b);
    stale.set(b.project_id, arr);
  }
  for (const [pid, list] of stale) {
    const p = projects.get(pid);
    if (!p) continue;
    statsInFlight.add(pid);
    void (async () => {
      changed(project, 'branches');
      return { ok: true };
    });

    app.get('/api/projects/:id/branches/:name/diff', async (req) => {
      const { project } = load(req, 'viewer');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const main = await ensureGit(ctx, project);
      const base = baseOf(project, b, main);
      const r = await git<{ files: { path: string }[]; additions: number; deletions: number; mergeBase: string; head: string }>('diff', {
        projectSlug: project.slug, worktree: b.dir, base,
      });
      db.prepare(`UPDATE branches SET files_changed = ?, stat_at = ? WHERE id = ?`).run(r.files.length, now(), b.id);
      return { branch: b.name, ...r, base };
    });

    app.get('/api/projects/:id/branches/:name/diff/file', async (req) => {
      const { project } = load(req, 'viewer');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const p = (req.query as { path?: string }).path;
      if (!p) throw badRequest('Missing path');
      const main = await ensureGit(ctx, project);
      return git('file-diff', { projectSlug: project.slug, worktree: b.dir, base: baseOf(project, b, main), path: p });
    });

    app.post('/api/projects/:id/branches/:name/merge', async (req) => {
      const { project } = load(req, 'editor');
      const b = loadBranch(project, (req.params as { name: string }).name);
      const body = mergeBody.parse(req.body ?? {});
      const main = await ensureGit(ctx, project);
      assertIdle(project, b.name, 'merging');
      assertIdle(project, null, 'merging into it');
      const r = await git<{ ok: boolean; sha?: string; conflicts?: string[]; upToDate?: boolean }>('merge', {
        projectSlug: project.slug, branch: b.name, worktree: b.dir, into: main,
      });
      if (!r.ok) {
        ctx.audit(req, 'branch_merge_conflict', project.id, { branch: b.name, conflicts: r.conflicts });
        return { ok: false, conflicts: r.conflicts ?? [], resolvePrompt: resolvePrompt(main, r.conflicts ?? []) };
      }
      const hasDependents = !!db.prepare(`SELECT 1 FROM branches WHERE project_id = ? AND base = ? AND status = 'active'`).get(project.id, b.name);
      const close = body.close && !hasDependents;
      if (close) await closeBranch(project, b, 'merged', r.sha ?? null);
      ctx.audit(req, 'branch_merge', project.id, { branch: b.name, into: main, sha: r.sha, closed: close });
      changed(project, 'branches');
      changed(project, 'history', null);
      void ctx.runs.autoStartPreview(project.id, null);
      return { ok: true, sha: r.sha ?? null, upToDate: !!r.upToDate, closed: close, into: main };
    });

    // ---------------- history / checkpoints / undo ----------------

    app.get('/api/projects/:id/history', async (req) => {
      const { project } = load(req, 'viewer');
      const q = req.query as { branch?: string; limit?: string };
      const b = branchParam(db, project, q.branch);
      const main = await ensureGit(ctx, project);
      const r = await git<{ commits: Commit[]; dirty: boolean; branch: string | null }>('history', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), limit: Math.min(200, Number(q.limit) || 60),
      });
      const shas = r.commits.map((c) => c.sha);
      const runs = new Map<string, Pick<RunRow, 'id' | 'conversation_id' | 'undo_sha' | 'user_id'> & { title: string | null }>();
      if (shas.length) {
        for (const x of db
          .prepare(
            `SELECT r.id, r.conversation_id, r.undo_sha, r.user_id, r.commit_sha, c.title FROM runs r LEFT JOIN conversations c ON c.id = r.conversation_id
             WHERE r.project_id = ? AND r.commit_sha IN (${shas.map(() => '?').join(',')})`,
          )
          .all(project.id, ...shas) as (Pick<RunRow, 'id' | 'conversation_id' | 'undo_sha' | 'user_id'> & { commit_sha: string; title: string | null })[])
          runs.set(x.commit_sha, x);
      }
      return {
        branch: b?.name ?? null,
        checkout: r.branch ?? (b ? b.name : main),
        main,
        dirty: r.dirty,
        commits: r.commits.map((c) => {
          const run = runs.get(c.sha);
          return {
            sha: c.sha, short: c.sha.slice(0, 7), message: c.message, time: new Date(c.time).toISOString(), author: c.author,
            filesChanged: c.filesChanged, insertions: c.insertions, deletions: c.deletions,
            isMerge: c.parents.length > 1, isRoot: c.parents.length === 0,
            run: run ? { id: run.id, conversationId: run.conversation_id, conversationTitle: run.title, undone: !!run.undo_sha } : null,
          };
        }),
      };
    });

    app.post('/api/projects/:id/checkpoint', async (req) => {
      const { project } = load(req, 'editor');
      const b = branchParam(db, project, (req.query as { branch?: string }).branch);
      const body = checkpointBody.parse(req.body ?? {});
      const main = await ensureGit(ctx, project);
      const msg = `nxeon: ${(body.message || 'manual checkpoint').replace(/\s+/g, ' ').trim().slice(0, 60)}`;
      const r = await git<{ sha: string | null; files?: number; skipped?: string }>('checkpoint', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), message: msg, expectBranch: b ? b.name : main,
      });
      if (r.skipped) throw conflict(`Checkpoint skipped: ${r.skipped === 'head_moved' ? 'the checkout is on another git branch' : r.skipped}`, 'checkpoint_skipped');
      if (r.sha) changed(project, 'history', b?.name ?? null);
      ctx.audit(req, 'checkpoint', project.id, { branch: b?.name ?? null, sha: r.sha });
      return { sha: r.sha, files: r.files ?? 0 };
    });

    async function revert(req: FastifyRequest, u: UserRow, project: ProjectRow, b: BranchRow | null, sha: string) {
      if (!SHA_RE.test(sha)) throw badRequest('Invalid commit');
      const main = await ensureGit(ctx, project);
      assertIdle(project, b?.name ?? null, 'undoing');
      const r = await git<{ ok: boolean; sha?: string | null; conflicts?: string[]; empty?: boolean }>('revert', {
        projectSlug: project.slug, ...(b ? { worktree: b.dir } : {}), sha, expectBranch: b ? b.name : main,
      });
      if (!r.ok) return { ok: false, conflicts: r.conflicts ?? [] };
      db.prepare(`UPDATE runs SET undo_sha = ? WHERE project_id = ? AND commit_sha LIKE ? || '%'`).run(r.sha ?? 'empty', project.id, sha);
      ctx.audit(req, 'undo', project.id, { branch: b?.name ?? null, sha, revert: r.sha, by: u.id });
      changed(project, 'history', b?.name ?? null);
      return { ok: true, sha: r.sha ?? null, empty: !!r.empty };
    }

    app.post('/api/projects/:id/history/:sha/revert', async (req) => {
      const { u, project } = load(req, 'editor');
      const b = branchParam(db, project, (req.query as { branch?: string }).branch);
      return revert(req, u, project, b, (req.params as { sha: string }).sha);
    });

    /** "Undo this run": revert the run's auto-checkpoint commit (creates a new commit). */
    app.post('/api/runs/:id/undo', async (req) => {
      const u = requireUser(req);
      const run = db.prepare(`SELECT * FROM runs WHERE id = ?`).get((req.params as { id: string }).id) as RunRow | undefined;
      if (!run) throw notFound('Run not found');
      const { project } = requireProject(db, u, run.project_id, 'editor');
      if (!run.commit_sha) throw conflict('This run has no checkpoint (it changed no files)', 'no_checkpoint');
      if (run.undo_sha) throw conflict('This run was already undone', 'already_undone');
      const b = run.branch ? getBranch(db, project.id, run.branch) : null;
      if (run.branch && !b) throw conflict(`Branch "${run.branch}" is closed`, 'branch_closed');
      return revert(req, u, project, b, run.commit_sha);
    });
  };
import chokidar, { type FSWatcher } from 'chokidar';
import path from 'node:path';
import fs from 'node:fs';
import type { FastifyBaseLogger } from 'fastify';
import type { Hub } from './hub.js';
import { HEAVY_DIRS } from './lib/safepath.js';
import type { FileChangeKind } from './shared/protocol.js';

const DEBOUNCE_MS = 150;

interface Watch {
  watcher: FSWatcher;
  pending: Map<string, FileChangeKind>;
  timer: NodeJS.Timeout | null;
}

const key = (projectId: string, branch: string | null) => `${projectId}\u0001${branch ?? ''}`;

/**
 * One chokidar watcher per watched checkout (a project's main dir, or a branch worktree under
 * .branches/<slug>/<dir>); started on first WS subscriber, closed when none remain.
 */
export class Watchers {
  private watches = new Map<string, Watch>();

  constructor(
    private hub: Hub,
    /** absolute root dir of the checkout, or null if unknown */
    private resolveRoot: (projectId: string, branch: string | null) => string | null,
    private log: FastifyBaseLogger,
  ) {}

  start(projectId: string, branch: string | null = null) {
    const k = key(projectId, branch);
    if (this.watches.has(k)) return;
    const root = this.resolveRoot(projectId, branch);
    if (!root || !fs.existsSync(root)) return;
    const watcher = chokidar.watch(root, {
      ignoreInitial: true,
      followSymlinks: false,
      depth: 30,
      ignored: (p: string) => {
        const rel = path.relative(root, p);
        if (!rel) return false;
        return rel.split(path.sep).some((seg) => HEAVY_DIRS.has(seg));
      },
    });
    const w: Watch = { watcher, pending: new Map(), timer: null };
    const onEvent = (kind: FileChangeKind) => (abs: string) => {
      const rel = path.relative(root, abs).split(path.sep).join('/');
      if (!rel || rel.startsWith('..')) return;
      w.pending.set(rel, kind);
      if (!w.timer)
        w.timer = setTimeout(() => {
          w.timer = null;
          const items = [...w.pending];
          w.pending.clear();
          for (const [p, kind] of items) this.hub.broadcastProject(projectId, { t: 'file_change', projectId, path: p, kind, branch });
        }, DEBOUNCE_MS);
    };
    for (const k of ['add', 'change', 'unlink', 'addDir', 'unlinkDir'] as const) watcher.on(k, onEvent(k));
    watcher.on('error', (err) => this.log.warn({ projectId, branch, err: (err as Error).message }, 'watcher error'));
    this.watches.set(k, w);
  }

  /** branch undefined = every watcher of the project. */
  stop(projectId: string, branch?: string | null) {
    const keys = branch === undefined ? [...this.watches.keys()].filter((k) => k.startsWith(`${projectId}\u0001`)) : [key(projectId, branch)];
    for (const k of keys) {
      const w = this.watches.get(k);
      if (!w) continue;
      if (w.timer) clearTimeout(w.timer);
      void w.watcher.close();
      this.watches.delete(k);
    }
  }

  stopAll() {
    for (const k of [...this.watches.keys()]) {
      const w = this.watches.get(k)!;
      if (w.timer) clearTimeout(w.timer);
      void w.watcher.close();
      this.watches.delete(k);
    }
  }

  isWatching(projectId: string, branch: string | null = null) {
    return this.watches.has(key(projectId, branch));
  }
}

