639	    async loadMessages(convId, silent) {
640	      if (!silent) set({ itemsLoading: true });
641	      try {
642	        const msgs = unwrap<Message[]>(await api.get<any>(`/conversations/${convId}/messages`), 'messages', 'items');
643	        if (get().activeConvId !== convId) return;
644	        const items = toItems(msgs);
645	        const runs = { ...get().runs };
646	        for (const m of msgs) {
647	          if (!m.runId || m.role !== 'assistant') continue;
648	          const evs = (m.events || []) as StoredEvent[];
649	          const existing = runs[m.runId];
650	          const maxSeq = evs.reduce((a, e) => Math.max(a, e.seq), -1);
651	          let rv: RunView;
652	          if (existing && existing.lastSeq >= maxSeq) rv = existing;
653	          else {
654	            const startedAt = m.run?.startedAt ? Date.parse(m.run.startedAt) : undefined;
655	            rv = replay(m.runId, evs.map((e) => ({ type: e.type, data: e.data, seq: e.seq, ts: (e as any).ts }) as SeqEvent), emptyRun(m.runId, 'running', startedAt));
656	            if (existing) for (const k of ['suggestions'] as const) if (existing[k] && !rv[k]) rv = { ...rv, [k]: existing[k] };
657	          }
658	          if (m.run) {
659	            if (m.run.status && (terminal(m.run.status) || !terminal(rv.status))) rv = setStatus(rv, m.run.status, m.run.endedAt ? Date.parse(m.run.endedAt) : undefined);
660	            if (m.run.startedAt && !rv.startedAt) rv = { ...rv, startedAt: Date.parse(m.run.startedAt) };
661	            if (m.run.endedAt && terminal(rv.status)) rv = { ...rv, endedAt: Date.parse(m.run.endedAt) };
662	            if (!rv.model && m.run.model) rv = { ...rv, model: m.run.model };
663	          }
664	          if (m.suggestions?.length) rv = { ...rv, suggestions: m.suggestions };
665	          runs[m.runId] = rv;
666	          if (!terminal(rv.status)) ensureSub(m.runId, rv.lastSeq + 1);
667	        }
668	        // user-only run references (assistant not created yet)
669	        for (const it of items) if (it.runId && !runs[it.runId]) {
670	          const st = it.run?.status ?? 'queued';
671	          runs[it.runId] = emptyRun(it.runId, st, it.run?.startedAt ? Date.parse(it.run.startedAt) : undefined);
672	          if (!terminal(st)) ensureSub(it.runId, 0);
673	        }
674	        set({ items, runs, itemsLoading: false });
675	      } catch (e) {
676	        set({ itemsLoading: false });
677	        if (!silent) set({ sendError: errInfo(e) });
678	      }
