687	      const att = ups.filter((u) => u.status === 'done' && u.result);
688	      if (!text.trim() && !att.length) return false;
689	      set({ sending: true, sendError: null });
690	      try {
691	        let convId = s.activeConvId;
692	        if (!convId) {
693	          const title = text.trim().split('\n')[0].slice(0, 60) || 'New conversation';
694	          const conv = unwrap<Conversation>(await api.post<any>(`/projects/${project.id}/conversations`, { title, model: s.prefs.model, mode: s.prefs.mode, branch: s.branch, topicId: s.topicFilter }), 'conversation');
