701	        const enabled = new Set(get().agents.filter((a) => a.enabled).map((a) => a.slug));
702	        const lead = s.activeConvId ? undefined : get().draftAgent;
703	        const body = {
704	          text, attachments: att.map((u) => u.result!.id), model: prefs.model, mode: prefs.mode, thinking: prefs.thinking,
705	          ...(lead && enabled.has(lead) ? { agent: lead } : {}),
706	        };
707	        const res = await api.post<{ runId: string; messageId: string; conversation?: Conversation }>(`/conversations/${convId}/prompt`, body);
708	        if (res.conversation?.id) set((st) => ({ conversations: st.conversations.map((c) => (c.id === res.conversation!.id ? { ...c, ...res.conversation } : c)), draftAgent: null }));
709	        const now = new Date().toISOString();
710	        const runId = res.runId;
711	        set((st) => ({
712	          items: [
713	            ...st.items,
714	            { key: res.messageId || 'local:' + runId, id: res.messageId, role: 'user', content: text, attachments: att.map((u) => u.result!), createdAt: now, runId },
715	            { key: 'run:' + runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId,
716	              run: { id: runId, status: 'queued', model: prefs.model, mode: prefs.mode, startedAt: now, inputTokens: 0, outputTokens: 0, cacheRead: 0, cacheWrite: 0, costUsd: 0 } },
717	          ],
718	          runs: { ...st.runs, [runId]: st.runs[runId] ?? emptyRun(runId, 'queued', Date.now()) },
719	          uploads: [], sending: false,
720	        }));
721	        att.forEach((u) => u.previewUrl && URL.revokeObjectURL(u.previewUrl));
722	        ensureSub(runId, 0);
723	        return true;
724	      } catch (e) {
725	        set({ sending: false, sendError: errInfo(e) });
