743	    handleServerMsg(msg) {
744	      const s = get();
745	      // Claude often starts dev servers itself via Bash; recheck the preview once commands settle.
746	      const schedulePreviewCheck = () => {
747	        window.clearTimeout(previewCheckTimer);
748	        previewCheckTimer = window.setTimeout(() => get().refreshPreview(), 1200);
749	      };
750	      switch (msg.t) {
751	        case 'run_event': {
752	          if (!subscribed.has(msg.runId) && !s.runs[msg.runId]) return;
753	          const { t: _t, runId, ...ev } = msg as any;
754	          putRun(msg.runId, (r) => applyRunEvent(r, ev as SeqEvent));
755	          // live context meter for the visible conversation
756	          const ctxTok = msg.type === 'compact' ? msg.data.postTokens
