import { useCallback, useEffect, useLayoutEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { ArrowDown, FileText, FoldVertical, Sparkles, Wand2, LayoutTemplate, Bug, BookOpen, TriangleAlert } from 'lucide-react';
import type { Attachment } from '@/lib/types';
import { useWs, type ChatItem } from './store';
import { AssistantMessage } from './AssistantMessage';
import { PromptBox } from './PromptBox';
import { fmtBytes, fmtTokens } from './toolFormat';
import { Spin, Tip } from './ui';
import { isTerminal } from './store';

function AttachmentChip({ a }: { a: Attachment }) {
  const img = a.mime?.startsWith('image/');
  if (img) {
    return (
      <a href={a.url} target="_blank" rel="noreferrer" className="block overflow-hidden rounded-lg border border-line transition hover:border-pink/50">
        <img src={a.thumbUrl || a.url} alt={a.filename} className="h-20 w-20 object-cover" loading="lazy" />
      </a>
    );
  }
  return (
    <a href={a.url} target="_blank" rel="noreferrer" className="flex items-center gap-2 rounded-lg border border-line bg-bg/50 px-2.5 py-1.5 text-xs transition hover:border-pink/50">
      <FileText size={14} className="text-pink" />
      <span className="max-w-[160px] truncate text-ink">{a.filename}</span>
      <span className="text-muted">{fmtBytes(a.size || 0)}</span>
    </a>
  );
}

function UserBubble({ item }: { item: ChatItem }) {
  return (
    <div className="flex justify-end">
      <div className="max-w-[85%] space-y-2">
        {item.attachments?.length > 0 && (
          <div className="flex flex-wrap justify-end gap-2">{item.attachments.map((a) => <AttachmentChip key={a.id} a={a} />)}</div>
        )}
        {item.content && (
          <div className="rounded-2xl rounded-br-md border border-pink/20 bg-gradient-to-br from-pink/[.14] to-pink/[.05] px-4 py-2.5 text-[14.5px] leading-relaxed text-ink shadow-[0_0_30px_-14px_rgba(255,62,138,.6)] whitespace-pre-wrap break-words">
            {item.content}
          </div>
        )}
        {item.userName && <div className="text-right text-[11px] text-muted/60">{item.userName}</div>}
      </div>
    </div>
  );
}

/** Manual compaction (`/compact`) rendered as a slim divider instead of a chat bubble. */
function CompactDivider({ item, instructions }: { item: ChatItem; instructions?: string }) {
  const run = useWs((s) => (item.runId ? s.runs[item.runId] : undefined));
  const status = run?.status ?? item.run?.status ?? 'queued';
  const live = !isTerminal(status);
  const c = run?.compact;
  const failed = status === 'error' || status === 'aborted';
  const label = live ? 'Compacting conversation…'
    : failed ? (status === 'aborted' ? 'Compaction stopped' : 'Compaction failed')
    : 'Conversation compacted';
  const body = (
    <div className="nxw-fade-in flex items-center gap-3 py-0.5 text-[12px]">
      <span className="h-px flex-1 bg-gradient-to-r from-transparent to-line" />
      <span className={clsx('flex shrink-0 items-center gap-2', failed ? 'text-bad/90' : 'text-muted')}>
        {live ? <Spin className="h-3 w-3" /> : failed ? <TriangleAlert size={13} /> : <FoldVertical size={13} className="text-warm/80" />}
        <span className={clsx(live && 'nxw-shimmer')}>{label}</span>
        {c && !live && <span className="font-mono text-[11px] text-muted/70">· {fmtTokens(c.preTokens)} → {fmtTokens(c.postTokens)} tokens</span>}
        {failed && run?.error && <span className="max-w-[260px] truncate text-[11px] text-bad/70">· {run.error}</span>}
      </span>
      <span className="h-px flex-1 bg-gradient-to-l from-transparent to-line" />
    </div>
  );
  return instructions ? <Tip label={<span><span className="text-muted">Instructions:</span> {instructions}</span>}>{body}</Tip> : body;
}

const STARTERS = [
  { icon: LayoutTemplate, label: 'Scaffold a web app', prompt: 'Set up a modern Vite + React + TypeScript app in this project with a clean landing page, and start the preview server.' },
  { icon: BookOpen, label: 'Explain this project', prompt: 'Explore this project and explain its structure, how to run it, and anything notable.' },
  { icon: Bug, label: 'Find & fix bugs', prompt: 'Review the code for bugs or broken behaviour, fix what you find, and summarize the changes.' },
  { icon: Wand2, label: 'Polish the UI', prompt: 'Improve the visual design and UX of the app: spacing, typography, responsiveness, and small delightful touches.' },
];

function EmptyChat() {
  const project = useWs((s) => s.project);
  const send = useWs((s) => s.send);
  const setDraft = useWs((s) => s.setDraft);
  const canEdit = useWs((s) => s.canEdit);
  return (
    <div className="flex h-full flex-col items-center justify-center px-6 pb-10 text-center">
      <div className="relative mb-5">
        <div className="absolute inset-0 rounded-full bg-pink/30 blur-2xl" />
        <div className="relative flex h-14 w-14 items-center justify-center rounded-2xl border border-pink/40 bg-panel2 shadow-[0_0_30px_-6px_rgba(255,62,138,.7)]">
          <Sparkles className="text-hot" size={24} />
        </div>
      </div>
      <h2 className="font-display text-lg tracking-[.08em] text-ink">{project?.name ?? 'Project'}</h2>
      <p className="mt-1.5 max-w-sm text-sm text-muted">{project?.description || 'What should we build? Claude can read, write and run code in this project.'}</p>
      {canEdit && (
        <div className="mt-7 grid w-full max-w-lg grid-cols-1 gap-2 sm:grid-cols-2">
          {STARTERS.map((s) => (
            <button key={s.label} type="button"
              onClick={(e) => (e.altKey || e.shiftKey ? setDraft(s.prompt) : send(s.prompt))}
              className="group flex items-center gap-2.5 rounded-xl border border-line bg-panel/60 px-3.5 py-3 text-left text-[13px] text-ink/90 transition-all hover:-translate-y-px hover:border-pink/40 hover:bg-pink/[.06] hover:shadow-[0_0_24px_-8px_rgba(255,62,138,.5)]">
              <s.icon size={16} className="shrink-0 text-pink/80 transition group-hover:text-hot" />
              {s.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export function Chat() {
  const items = useWs((s) => s.items);
  const runs = useWs((s) => s.runs);
  const itemsLoading = useWs((s) => s.itemsLoading);
  const canEdit = useWs((s) => s.canEdit);
  const retry = useWs((s) => s.retry);
  const activeConvId = useWs((s) => s.activeConvId);
  const scroller = useRef<HTMLDivElement>(null);
  const content = useRef<HTMLDivElement>(null);
  const stick = useRef(true);
  const [showJump, setShowJump] = useState(false);

  const toBottom = useCallback((smooth = false) => {
    const el = scroller.current; if (!el) return;
    el.scrollTo({ top: el.scrollHeight, behavior: smooth ? 'smooth' : 'auto' });
  }, []);

  const onScroll = () => {
    const el = scroller.current; if (!el) return;
    const dist = el.scrollHeight - el.scrollTop - el.clientHeight;
    stick.current = dist < 80;
    setShowJump(dist > 240);
  };

  // stick to bottom when content grows (streaming)
  useEffect(() => {
    const el = content.current; if (!el) return;
    const ro = new ResizeObserver(() => { if (stick.current) toBottom(); });
    ro.observe(el);
    return () => ro.disconnect();
  }, [toBottom]);

  // new conversation / new messages from the user → jump to bottom
  const lastKey = items[items.length - 1]?.key;
  const lastUser = [...items].reverse().find((i) => i.role === 'user')?.key;
  useLayoutEffect(() => { stick.current = true; toBottom(); }, [activeConvId, lastUser, toBottom]);
  useEffect(() => { if (stick.current) toBottom(); }, [lastKey, toBottom]);

  const lastAssistant = [...items].reverse().find((i) => i.role === 'assistant' && i.kind !== 'compact')?.key;
  const compactInstr = (runId?: string | null) => items.find((i) => i.role === 'user' && i.kind === 'compact' && i.runId === runId)?.content.replace(/^\/compact\s*/, '') || undefined;

  return (
    <div className="relative flex h-full min-h-0 flex-col">
      <div className="relative min-h-0 flex-1">
      <div ref={scroller} onScroll={onScroll} className="nxw-scroll absolute inset-0 overflow-y-auto">
        <div ref={content} className="mx-auto w-full max-w-[820px] px-4 pb-6 pt-6 sm:px-6">
          {itemsLoading && !items.length ? (
            <div className="flex justify-center py-20"><Spin /></div>
          ) : !items.length ? (
            <div className="h-[calc(100vh-280px)] min-h-[360px]"><EmptyChat /></div>
          ) : (
            <div className="space-y-7">
              {items.map((it) => it.kind === 'compact' ? (it.role === 'user' ? null : <CompactDivider key={it.key} item={it} instructions={compactInstr(it.runId)} />)
                : it.role === 'user' ? <UserBubble key={it.key} item={it} /> : (
                <AssistantMessage
                  key={it.key} run={it.runId ? runs[it.runId] : undefined} fallbackText={it.content} model={it.run?.model}
                  suggestions={it.suggestions} isLast={it.key === lastAssistant} canEdit={canEdit}
                  onRetry={it.runId ? () => retry(it.runId!) : undefined}
                />
              ))}
            </div>
          )}
        </div>
      </div>
      <button
        type="button" onClick={() => { stick.current = true; toBottom(true); }}
        className={clsx(
          'absolute bottom-3 left-1/2 z-10 -translate-x-1/2 transition-all duration-200',
          'inline-flex items-center gap-1.5 rounded-full border border-pink/40 bg-panel/90 px-3 py-1 text-xs text-ink shadow-[0_0_20px_-4px_rgba(255,62,138,.6)] backdrop-blur',
          showJump ? 'pointer-events-auto translate-y-0 opacity-100' : 'pointer-events-none translate-y-2 opacity-0',
        )}
      >
        <ArrowDown size={12} /> Jump to latest
      </button>
      </div>
      <PromptBox />
    </div>
  );
}
