export class NexusEngine {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private cb: EngineCallbacks;
  private dpr = 1; private W = 0; private H = 0;
  private raf = 0; private last = 0; private time = 0;
  private running = false;
  private reduced: boolean;
  private dirty = true;

  nodes: SimNode[] = [];
  /** satellites (not part of the force simulation; positioned around their owner every frame) */
  sats: SimNode[] = [];
  private satStrands: Strand[] = [];
  private satsOf = new Map<string, SimNode[]>();
  private branchIdx = new Map<string, SimNode>(); // `${projectId}|${branch}` → node
  private showSats = false;
  /** camera scale of the last fit(): semantic zoom opens satellites only when zoomed in beyond it */
  private fitK = 1;
  private byId = new Map<string, SimNode>();
  private strands: Strand[] = [];
  private nodeStrands = new Map<string, Strand[]>();
  private pulses: Pulse[] = [];
  private stars: Star[] = [];
  private sim: Simulation<SimNode, SimulationLinkDatum<SimNode>>;
  private positions = loadPositions();

  // camera
  cam = { x: 0, y: 0, k: 1 };
  private target = { x: 0, y: 0, k: 1 };
  private tween: { from: { x: number; y: number; k: number }; to: { x: number; y: number; k: number }; t0: number; dur: number; done?: () => void } | null = null;
  private outerR = 300;
  private webPath: Path2D | null = null;
  private bgCache: HTMLCanvasElement | null = null;
  private spokePath: Path2D | null = null;

  // interaction
  hovered: SimNode | null = null;
  private focusId: string | null = null; // externally highlighted (list hover)
  private pointers = new Map<number, { x: number; y: number }>();
  private drag: { mode: 'pan' | 'node' | 'pinch'; node?: SimNode; sx: number; sy: number; moved: boolean; camX: number; camY: number; dist?: number; k0?: number } | null = null;
  private hoverEl: HTMLElement | null = null;
  private icons = new Map<string, HTMLImageElement>();
  private sprites = new Map<string, HTMLCanvasElement>();
  private ro: ResizeObserver;
  private disposed = false;

  constructor(canvas: HTMLCanvasElement, cb: EngineCallbacks = {}) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false })!;
    this.cb = cb;
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.sim = forceSimulation<SimNode>([]).stop();
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(canvas);
    this.resize();
    this.makeStars();
    this.bind();
    document.addEventListener('visibilitychange', this.onVis);
    this.start();
  }

  // ---------- public API ----------
  setIcons(map: Map<string, HTMLImageElement>) { this.icons = map; this.dirty = true; }
  setHoverElement(el: HTMLElement | null) { this.hoverEl = el; }
  setFocus(id: string | null) { this.focusId = id; this.dirty = true; }

  /** Update one project's (or sub-project's / branch's) status (from run_status). */
  setStatus(projectId: string, status: NodeStatus, branch?: string | null) {
    const p = this.nodeOf(projectId);
    if (!p) return;
    const targets = [p];
    if (branch) { const b = this.branchIdx.get(`${projectId}|${branch}`); if (b) targets.push(b); }
    for (const n of targets) {
      if (n.status !== status && status === 'running') n.flash = 1;
      n.status = status;
    }
    this.dirty = true;
  }

  /** graph_pulse: fire light along all strands of a node — starting at the branch / sub-project satellite if any. */
  pulse(projectId: string, intensity = 0.5, branch?: string | null) {
    const n = this.nodeOf(projectId);
    if (!n) return;
    const chain: SimNode[] = [];
    const b = branch ? this.branchIdx.get(`${projectId}|${branch}`) : undefined;
    if (b) chain.push(b);
    chain.push(n);
    if (n.owner) chain.push(n.owner); // sub-project → its parent
    for (const x of chain) {
      x.flash = Math.min(1.5, x.flash + 0.6 + intensity * 0.4);
      x.activity = Math.min(1, x.activity + intensity * 0.05);
    }
    if (this.reduced) { this.dirty = true; return; }
    const count = 1 + Math.round(intensity * 4);
    // satellite strands: light flows from the satellite inward to its owner
    for (const x of chain) {
      if (!x.owner) continue;
      const st = this.satStrands.find((q) => q.b === x);
      if (st) for (let i = 0; i < count; i++) this.spawn(st, -1, x.rgb, 0.8 + intensity * 0.6, i * -0.08);
    }
    const hub = chain[chain.length - 1]!;
    hub.ripples.push(0);
    if (hub.ripples.length > 4) hub.ripples.shift();
    for (const s of this.nodeStrands.get(hub.id) || []) {
      if (s.sat) continue;
      for (let i = 0; i < count; i++) this.spawn(s, s.a === hub ? 1 : -1, hub.rgb, 1 + intensity, i * -0.08);
    }
  }

  /** Show all satellites (sub-projects, branches, topics) regardless of zoom/hover. */
  setSatellites(on: boolean) {
    if (this.showSats === on) return;
    this.showSats = on;
    // make room for fanned-out sub-projects
    const c = this.sim.force('collide') as ReturnType<typeof forceCollide<SimNode>> | undefined;
    if (c) { c.radius((n) => this.collideR(n)); if (!this.reduced) this.sim.alpha(Math.max(this.sim.alpha(), 0.25)); }
    return {
      id, kind, data, r: kind === 'core' ? CORE_R : kind === 'ghost' ? 15 : 16, ringR: 0, color, rgb: hexToRgb(color),
      status: data?.status || 'idle', activity: data?.activity || 0, phase: (hashStr(id) % 1000) / 1000 * TAU,
      flash: 0, ripples: [], pinned: false, label: kind === 'ghost' ? 'New project' : data?.name || 'core', x: 0, y: 0,
      expand: 0, holdUntil: 0, vis: 1,
    };
  }

  private makeStars() {
    const rnd = mulberry(1337);
    this.stars = Array.from({ length: 240 }, () => ({ x: rnd() * 4000, y: rnd() * 4000, z: 0.04 + rnd() * rnd() * 0.35, tw: rnd() * TAU, s: rnd() < 0.08 ? 1.6 : rnd() < 0.4 ? 1.1 : 0.7 }));
  }

  private buildWeb() {
    // Orb-web: radial spokes + sagging capture rings with slight organic jitter.
    const rnd = mulberry(424242);
    const spokes = 28;
    const R = this.outerR;
    const angles = Array.from({ length: spokes }, (_, i) => (i / spokes) * TAU + (rnd() - 0.5) * 0.08);
    const sp = new Path2D();
    for (const a of angles) { sp.moveTo(Math.cos(a) * 46, Math.sin(a) * 46); sp.lineTo(Math.cos(a) * R * 1.35, Math.sin(a) * R * 1.35); }
    this.spokePath = sp;
    const web = new Path2D();
    const gap = 46;
    for (let r = 64; r < R * 1.25; r += gap * (0.88 + rnd() * 0.24)) {
      const pts = angles.map((a) => { const rr = r * (0.97 + rnd() * 0.06); return [Math.cos(a) * rr, Math.sin(a) * rr, rr] as const; });
      web.moveTo(pts[0][0], pts[0][1]);
      for (let i = 0; i < spokes; i++) {
        const p = pts[i], q = pts[(i + 1) % spokes];
        const am = (angles[i] + (i === spokes - 1 ? angles[0] + TAU : angles[(i + 1) % spokes])) / 2;
        const sag = ((p[2] + q[2]) / 2) * 0.955;
        web.quadraticCurveTo(Math.cos(am) * sag, Math.sin(am) * sag, q[0], q[1]);
      }
    }
    this.webPath = web;
  }

  private spawn(s: Strand, dir: 1 | -1, rgb: [number, number, number], size = 1, t0 = 0) {
    if (this.pulses.length >= MAX_PULSES) this.pulses.shift();
    const len = Math.max(60, Math.hypot(s.b.x - s.a.x, s.b.y - s.a.y));
    this.pulses.push({ s, t: t0, dir, rgb, size, speed: (150 + Math.random() * 90) / len * (size > 1 ? 1.4 : 1) });
  }

  private sprite(rgb: [number, number, number]) {
    const key = rgb.join(',');
    let c = this.sprites.get(key);
    if (!c) {
      c = document.createElement('canvas'); c.width = c.height = 64;
      const g = c.getContext('2d')!;
      const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
      gr.addColorStop(0, `rgba(255,240,248,1)`);
    // parallax starfield / dust (screen space)
    for (const s of this.stars) {
      const px = ((s.x - cam.x * s.z * k) % W + W) % W;
      const py = ((s.y - cam.y * s.z * k) % H + H) % H;
      const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(this.time * (0.6 + s.z * 3) + s.tw));
      ctx.fillStyle = s.z > 0.25 ? `rgba(255,170,205,${0.32 * tw})` : `rgba(246,233,240,${0.18 * tw})`;
      ctx.fillRect(px, py, s.s, s.s);
    }

    // world transform
    ctx.setTransform(dpr * k, 0, 0, dpr * k, dpr * (W / 2 - cam.x * k), dpr * (H / 2 - cam.y * k));
    const hair = 1 / k;

    // web
    if (this.spokePath && this.webPath) {
      ctx.lineWidth = 0.8 * hair;
      ctx.strokeStyle = 'rgba(255,62,138,0.11)';
      ctx.stroke(this.spokePath);
      ctx.strokeStyle = 'rgba(255,111,174,0.095)';
      ctx.stroke(this.webPath);
    }
    // web glow fade at center
