// Nexus Chat: conversations that work across all projects a user may edit.
// The app is authoritative for scope: permissions are recomputed on every run, the sandbox gets exactly the
// gids of the projects in scope, and claudebox only validates ranges/paths (see claudebox/PROTOCOL.md "Sandbox").
import fs from 'node:fs';
import path from 'node:path';
import { z } from 'zod';
import type { EffectiveRole, ProjectRow, UserRow } from '../auth.js';
import { hasRole, maxRole } from '../auth.js';
import type { Config } from '../config.js';
import type { DB } from '../db.js';
import type { ProjectRole } from '../shared/protocol.js';
import { activeBranches, BRANCH_RE, claudeboxCwd, type BranchRow } from './branches.js';
import { multiProjectSandbox, NEXUS_BASE, SANDBOX_HOMES, type SandboxSpec } from './sandbox.js';

export const NEXUS_DIR = '/workspace/.nexus';
export const NEXUS_MAX_ID = 9999;
/** Index budget: ~1.5k tokens (≈4 chars/token). */
export const INDEX_MAX_CHARS = 6000;
export const MAX_FOCUS = 8;

// ---------------------------------------------------------------- identity

/** The user's Nexus identity uid (30001-39999), assigned on first use; monotonic, never reused. */
export function nexusUid(db: DB, userId: string): number {
  return db.transaction(() => {
    const row = db.prepare(`SELECT nexus_sandbox_id FROM users WHERE id = ?`).get(userId) as { nexus_sandbox_id: number | null } | undefined;
    if (!row) throw new Error('unknown user');
    if (row.nexus_sandbox_id != null) return NEXUS_BASE + row.nexus_sandbox_id;
    const maxRow = (db.prepare(`SELECT COALESCE(MAX(nexus_sandbox_id), 0) AS m FROM users`).get() as { m: number }).m;
    const seqRow = db.prepare(`SELECT value FROM settings WHERE key = 'nexus_seq'`).get() as { value: string } | undefined;
    const id = Math.max(maxRow, seqRow ? Number(JSON.parse(seqRow.value)) || 0 : 0) + 1;
    if (id > NEXUS_MAX_ID) throw new Error('No Nexus identities left');
    db.prepare(`INSERT INTO settings(key, value) VALUES ('nexus_seq', ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value`).run(JSON.stringify(id));
    db.prepare(`UPDATE users SET nexus_sandbox_id = ? WHERE id = ?`).run(id, userId);
    return NEXUS_BASE + id;
  })();
}

/** Private scratch cwd of a Nexus identity (created 1000:<uid> 2770 by the claudebox helper). */
export const nexusCwd = (uid: number) => `${NEXUS_DIR}/${uid}`;

// ---------------------------------------------------------------- scope

export interface ScopeProject {
  project: ProjectRow;
  role: EffectiveRole;
  branches: BranchRow[];
  /** a project run is active on the main checkout */
  busy: boolean;
}

export interface NexusScope {
  /** projects the run may read + write (admin: all; member: effective role >= editor) */
  projects: ScopeProject[];
  /** projects the user can only view — excluded from the run (no safe read-only mechanism; see PROTOCOL.md) */
  viewOnly: number;
}

/**
 * Projects a Nexus run of `user` may access. Viewer-only projects are EXCLUDED entirely: the sandbox grants access
 * through the project's group, which is read-write by design, so there's no way to give a run read-only access.
 * Archived projects and projects without a sandbox id are excluded too.
 */
export function nexusScope(db: DB, user: Pick<UserRow, 'id' | 'role'>): NexusScope {
  let rows: { p: ProjectRow; role: EffectiveRole }[];
  if (user.role === 'admin') {
    rows = (db.prepare(`SELECT * FROM projects WHERE archived = 0 ORDER BY COALESCE(last_active_at, created_at) DESC`).all() as ProjectRow[]).map(
      (p) => ({ p, role: 'admin' as const }),
    );
  } else {
    rows = (
      db
        .prepare(
          `SELECT p.*, m.role AS member_role, pm.role AS parent_role FROM projects p
           LEFT JOIN project_members m ON m.project_id = p.id AND m.user_id = ?
           LEFT JOIN project_members pm ON p.parent_id IS NOT NULL AND pm.project_id = p.parent_id AND pm.user_id = ?
           WHERE (m.role IS NOT NULL OR pm.role IS NOT NULL) AND p.archived = 0
           ORDER BY COALESCE(p.last_active_at, p.created_at) DESC`,
        )
        .all(user.id, user.id) as (ProjectRow & { member_role: ProjectRole | null; parent_role: ProjectRole | null })[]
    ).map((p) => ({ p, role: maxRole(p.member_role, p.parent_role)! }));
  }
  const busyRows = db.prepare(`SELECT DISTINCT project_id FROM runs WHERE status IN ('queued','running') AND project_id IS NOT NULL AND branch IS NULL`).all() as { project_id: string }[];
  const busy = new Set(busyRows.map((r) => r.project_id));
  const out: ScopeProject[] = [];
  let viewOnly = 0;
  for (const { p, role } of rows) {
    if (p.sandbox_id == null) continue;
    if (!hasRole(role, 'editor')) {
      viewOnly++;
      continue;
    }
    out.push({ project: p, role, branches: activeBranches(db, p.id), busy: busy.has(p.id) });
  }
  return { projects: out, viewOnly };
}

export interface FocusItem {
  slug: string;
  branch: string | null;
}
const FOCUS_RE = /^([a-z0-9][a-z0-9-]{0,47})(?:@([a-z0-9][a-z0-9/-]{0,63}))?$/;

/** Validate `#slug` / `#slug@branch` focus mentions against the scope. Throws a message string on unknown items. */
export function resolveFocus(scope: NexusScope, raw: string[]): { items: { sp: ScopeProject; branch: BranchRow | null }[]; errors: string[] } {
  const items: { sp: ScopeProject; branch: BranchRow | null }[] = [];
  const errors: string[] = [];
  const seen = new Set<string>();
  for (const r of raw.slice(0, MAX_FOCUS * 2)) {
    const m = FOCUS_RE.exec(r.trim().replace(/^#/, ''));
    if (!m) {
      errors.push(`#${r}`);
      continue;
    }
    const sp = scope.projects.find((x) => x.project.slug === m[1]);
    if (!sp) {
      errors.push(`#${m[1]}`);
      continue;
    }
    let branch: BranchRow | null = null;
    if (m[2] && m[2] !== 'main' && m[2] !== sp.project.git_main) {
      if (!BRANCH_RE.test(m[2])) {
        errors.push(`#${r}`);
        continue;
      }
      branch = sp.branches.find((b) => b.name === m[2]) ?? null;
      if (!branch) {
        errors.push(`#${m[1]}@${m[2]}`);
        continue;
      }
    }
    const key = `${sp.project.id}|${branch?.name ?? ''}`;
    if (seen.has(key)) continue;
    seen.add(key);
    items.push({ sp, branch });
    if (items.length >= MAX_FOCUS) break;
  }
  return { items, errors };
}

/** Sandbox spec + dirs for a Nexus run: groups = every project in scope; addDirs = main checkouts + focused branches. */
export function nexusRunSpec(cfg: Config, uid: number, scope: NexusScope, focus: { sp: ScopeProject; branch: BranchRow | null }[]) {
  const sandbox: SandboxSpec = multiProjectSandbox(uid, scope.projects.map((x) => x.project));
  const addDirs = scope.projects.map((x) => claudeboxCwd(cfg, x.project.slug, null));
  for (const f of focus) if (f.branch) addDirs.push(claudeboxCwd(cfg, f.sp.project.slug, f.branch));
  return { sandbox: { ...sandbox, home: `${SANDBOX_HOMES}/${uid}` }, addDirs: [...new Set(addDirs)].slice(0, 64), cwd: nexusCwd(uid) };
}

// ---------------------------------------------------------------- tech hints

const techCache = new Map<string, { key: string; hint: string }>();
const TECH: [string, string][] = [
  ['next', 'Next.js'], ['nuxt', 'Nuxt'], ['astro', 'Astro'], ['@sveltejs/kit', 'SvelteKit'], ['svelte', 'Svelte'], ['vue', 'Vue'],
  ['solid-js', 'Solid'], ['preact', 'Preact'], ['react', 'React'], ['@angular/core', 'Angular'], ['express', 'Express'],
  ['fastify', 'Fastify'], ['hono', 'Hono'], ['three', 'three.js'], ['phaser', 'Phaser'], ['vite', 'Vite'], ['tailwindcss', 'Tailwind'],
  ['typescript', 'TS'],
];

/** Short tech hint from package.json deps / marker files (cached by mtime). '' = empty/unknown. */
export function techHint(dir: string): string {
  const files = ['package.json', 'index.html', 'requirements.txt', 'pyproject.toml', 'go.mod', 'Cargo.toml'];
  const stats = files.map((f) => {
    try {
      return fs.statSync(path.join(dir, f)).mtimeMs;
    } catch {
      return 0;
    }
  });
  const key = stats.join(',');
  const cached = techCache.get(dir);
  if (cached && cached.key === key) return cached.hint;
  let hint = '';
  if (stats[0]) {
    try {
      const pkg = JSON.parse(fs.readFileSync(path.join(dir, 'package.json'), 'utf8').slice(0, 200_000)) as Record<string, Record<string, string>>;
      const deps = { ...(pkg.dependencies ?? {}), ...(pkg.devDependencies ?? {}) };
      const found: string[] = [];
      for (const [dep, label] of TECH) {
        if (!(dep in deps)) continue;
        if (label === 'React' && found.some((x) => ['Next.js', 'Preact'].includes(x))) continue;
        if (label === 'Svelte' && found.includes('SvelteKit')) continue;
        if (label === 'Vue' && found.includes('Nuxt')) continue;
        found.push(label);
        if (found.length >= 4) break;
      }
      hint = found.length ? found.join('+') : 'Node';
    } catch {
      hint = 'Node';
    }
  } else if (stats[1]) hint = 'static HTML';
  else if (stats[2] || stats[3]) hint = 'Python';
  else if (stats[4]) hint = 'Go';
  else if (stats[5]) hint = 'Rust';
  techCache.set(dir, { key, hint });
  return hint;
}

function topLevel(dir: string, max = 18): string {
  try {
    const ents = fs.readdirSync(dir, { withFileTypes: true })
      .filter((e) => !['.git', 'node_modules', '.DS_Store', 'dist', '.next', '.venv', '__pycache__'].includes(e.name))
      .sort((a, b) => Number(b.isDirectory()) - Number(a.isDirectory()) || a.name.localeCompare(b.name));
    const names = ents.slice(0, max).map((e) => (e.isDirectory() ? `${e.name}/` : e.name));
    return names.join(', ') + (ents.length > max ? `, …(+${ents.length - max})` : '') || '(empty)';
  } catch {
    return '(unreadable)';
  }
}

export function ago(ms: number | null | undefined, nowMs = Date.now()): string {
  if (!ms) return 'never';
  const s = Math.max(0, (nowMs - ms) / 1000);
  if (s < 3600) return `${Math.max(1, Math.round(s / 60))}m ago`;
  if (s < 86400) return `${Math.round(s / 3600)}h ago`;
  return `${Math.round(s / 86400)}d ago`;
}

const oneLine = (s: string, n: number) => {
  const t = s.replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t;
};

// ---------------------------------------------------------------- index

export interface IndexOptions {
  cfg: Pick<Config, 'projectsDir' | 'claudeboxProjectsDir' | 'publicUrl'>;
  /** override the char budget (tests) */
  maxChars?: number;
  now?: number;
  /** tech hint resolver (tests) */
  tech?: (sp: ScopeProject) => string;
  listing?: (sp: ScopeProject, b: BranchRow | null) => string;
}

/**
 * Compact project index for the system prompt (≈1.5k tokens max). Focused projects get a detail block first;
 * the rest get one line each, progressively shortened (description → dropped → slugs only) to fit the budget.
 */
export function buildNexusIndex(scope: NexusScope, focus: { sp: ScopeProject; branch: BranchRow | null }[], o: IndexOptions): string {
  const max = o.maxChars ?? INDEX_MAX_CHARS;
  const now = o.now ?? Date.now();
  const tech = o.tech ?? ((sp) => techHint(path.join(o.cfg.projectsDir, sp.project.slug)));
  const listing = o.listing ?? ((sp, b) => topLevel(b ? path.join(o.cfg.projectsDir, '.branches', sp.project.slug, b.dir) : path.join(o.cfg.projectsDir, sp.project.slug)));
  const root = o.cfg.claudeboxProjectsDir;
  const slugOf = new Map(scope.projects.map((x) => [x.project.id, x.project.slug]));
  const header = [
    `PROJECTS IN SCOPE (${scope.projects.length}): dir = ${root}/<slug>, branch dir = ${root}/.branches/<slug>/<branch with / → _>, preview = ${o.cfg.publicUrl}/preview/<slug>/`,
  ];
  if (!scope.projects.length) header.push('(none — the user has no projects with edit access)');
  const focusIds = new Set(focus.map((f) => f.sp.project.id));
  const blocks: string[] = [];
  if (focus.length) {
    blocks.push('FOCUS (the user #mentioned these — they are the targets):');
    for (const f of focus) {
      const p = f.sp.project;
      const dir = claudeboxCwd(o.cfg as Config, p.slug, f.branch);
      const lines = [
        `## ${p.slug} — ${oneLine(p.name, 60)}${p.parent_id && slugOf.get(p.parent_id) ? ` (sub-project of ${slugOf.get(p.parent_id)})` : ''}`,
        `dir: ${dir}${f.branch ? ` (branch "${f.branch.name}", worktree of ${p.slug})` : ''}`,
        p.description ? `about: ${oneLine(p.description, 360)}` : '',
        `tech: ${tech(f.sp) || 'empty/unknown'} · preview: ${o.cfg.publicUrl}/preview/${p.slug}${f.branch ? `--${f.branch.dir}` : ''}/ · active ${ago(p.last_active_at, now)}${f.sp.busy ? ' · BUSY: a run is active in this project' : ''}`,
        f.sp.branches.length ? `branches: ${f.sp.branches.map((b) => b.name).slice(0, 12).join(', ')}` : '',
        `files: ${listing(f.sp, f.branch)}`,
      ];
      blocks.push(lines.filter(Boolean).join('\n'));
    }
  }
  const rest = scope.projects.filter((x) => !focusIds.has(x.project.id) || focus.some((f) => f.sp.project.id === x.project.id && f.branch));
  const line = (sp: ScopeProject, level: number) => {
    const p = sp.project;
    const parent = p.parent_id && slugOf.get(p.parent_id) ? ` (sub of ${slugOf.get(p.parent_id)})` : '';
    if (level >= 3) return p.slug;
    const parts = [`- ${p.slug}${level <= 1 ? ` "${oneLine(p.name, 40)}"` : ''}${parent}`];
    if (level === 0 && p.description) parts[0] += ` — ${oneLine(p.description, 90)}`;
    else if (level === 1 && p.description) parts[0] += ` — ${oneLine(p.description, 45)}`;
    const meta: string[] = [];
    const t = tech(sp);
    if (t) meta.push(t);
    if (sp.branches.length && level <= 1) meta.push(`br: ${sp.branches.map((b) => b.name).slice(0, 5).join(',')}${sp.branches.length > 5 ? ',…' : ''}`);
    meta.push(ago(p.last_active_at, now));
    if (sp.busy) meta.push('BUSY');
    return `${parts[0]} [${meta.join(' · ')}]`;
  };
  const compose = (level: number, limit: number) => {
    const shown = rest.slice(0, limit);
    const hidden = rest.length - shown.length;
    const others = focus.length ? (rest.length ? ['OTHER PROJECTS:'] : []) : [];
    const body = level >= 3 ? [shown.map((sp) => line(sp, 3)).join(', ')] : shown.map((sp) => line(sp, level));
    if (hidden > 0) body.push(`…and ${hidden} more (ask the user to #mention one if needed)`);
    return [...header, ...blocks, ...others, ...body].filter((l) => l !== '').join('\n');
  };
  for (const level of [0, 1, 2, 3]) {
    const s = compose(level, rest.length);
    if (s.length <= max) return s;
  }
  // still too long: show as many slugs as fit
  let lo = 0;
  let hi = rest.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (compose(3, mid).length <= max) lo = mid;
    else hi = mid - 1;
  }
  const s = compose(3, lo);
  return s.length <= max ? s : s.slice(0, max - 1) + '…';
}

export function buildNexusSystemPrompt(index: string, cwd: string, viewOnly: number): string {
  return [
    'You are the Nexus assistant of the Nxeon Workspace: one chat that can work across several of the user\'s projects at once.',
    `Your cwd (${cwd}) is a private scratch dir, not a project. Work in the project dirs below using absolute paths.`,
    '',
    index,
    viewOnly ? `(${viewOnly} view-only project${viewOnly === 1 ? ' is' : 's are'} not available here.)` : '',
    '',
    'RULES:',
    '- Only touch the projects listed above, nothing else (other dirs are not accessible). Never create or delete project dirs.',
    '- Small or cross-project tasks (a few files per project, consistency fixes, comparisons, questions): do them directly in the project dirs.',
    '- Large per-project work (new features, rewrites, multi-step builds, anything needing a preview/debug loop): do not do it here — propose a handoff so it runs in that project\'s own chat with its own context.',
    '- Each project is its own git repo. The workspace commits an automatic checkpoint for every project you change after your run (one "Undo" reverts them all). Do not commit, branch, reset or stash yourself.',
    '- Do not start dev servers, curl previews or take screenshots — previews start automatically for changed projects.',
    '- Projects marked BUSY have a run in progress: avoid editing them.',
    '',
    'TOKEN BUDGET — be economical; the user pays per token:',
    '- Simplest approach that fully satisfies the request; no frameworks/npm/build steps for simple pages unless asked.',
    '- Few tool calls: read only the files you need, don\'t re-read what you just wrote, prefer one Write over many Edits for new files, no exploratory listing of projects you don\'t need.',
    '- No builds/tests/type-checks for trivial changes unless asked. Keep the final reply short: what changed, per project.',
    '- You have internet access. There is no sudo/apt.',
    '',
    'HANDOFFS — only when delegating is clearly better (large per-project work), at the very end of the reply add one line (valid JSON, no code fence, max 4 items):',
    '<nx-handoff>[{"project":"<slug>","branch":null,"prompt":"Complete, self-contained instructions for that project\'s chat"}]</nx-handoff>',
    'The user decides whether to send each one (they are never sent automatically). Never mention the block.',
    '',
    'At the very end of EVERY final reply, append 2-3 short actionable follow-up suggestions in exactly this format (valid JSON array on one line, no code fences):',
    '<nx-suggestions>[{"label":"Short button text","prompt":"The full prompt to send if clicked","kind":"next"}]</nx-suggestions>',
    'kind must be one of: next, fix, test, deploy, explain. The block is hidden from the user and rendered as clickable chips. Never mention it.',
  ].filter((l, i, a) => !(l === '' && a[i - 1] === '')).join('\n');
}

// ---------------------------------------------------------------- handoffs

export interface Handoff {
  project: string;
  branch: string | null;
  prompt: string;
  /** set once the user sent it */
  sent?: { conversationId: string; runId: string; at: number; projectId: string };
}
const handoffItem = z.object({
  project: z.string().trim().regex(/^[a-z0-9][a-z0-9-]{0,47}$/),
  branch: z.string().trim().max(64).nullable().optional(),
  prompt: z.string().trim().min(1).max(8000),
});

/** Parse the LAST complete <nx-handoff> block; keep items for projects in `slugs` (max 4). Invalid → []. */
export function parseHandoffs(full: string, slugs: Set<string>): Handoff[] {
  const re = /<nx-handoff[^>]*>([\s\S]*?)<\/nx-handoff>/g;
  let m: RegExpExecArray | null;
  let last: string | null = null;
  while ((m = re.exec(full))) last = m[1] ?? null;
  if (last == null) return [];
  const body = last.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    return [];
  }
  if (!Array.isArray(parsed)) parsed = [parsed];
  const out: Handoff[] = [];
  for (const raw of parsed as unknown[]) {
    const r = handoffItem.safeParse(raw);
    if (!r.success || !slugs.has(r.data.project)) continue;
    const branch = r.data.branch && r.data.branch !== 'main' && BRANCH_RE.test(r.data.branch) ? r.data.branch : null;
    if (out.some((h) => h.project === r.data.project && h.branch === branch)) continue;
    out.push({ project: r.data.project, branch, prompt: r.data.prompt });
    if (out.length >= 4) break;
  }
  return out;
}

// ---------------------------------------------------------------- touch detection

/**
 * Which project checkouts a tool call refers to: absolute paths under the claudebox projects dir in file inputs
 * or Bash commands. Returns `slug` + worktree dir (null = main).
 */
export function touchedPaths(root: string, name: string, input: unknown): { slug: string; worktree: string | null }[] {
  if (!input || typeof input !== 'object') return [];
  const i = input as Record<string, unknown>;
  const texts: string[] = [];
  for (const k of ['file_path', 'path', 'notebook_path']) if (typeof i[k] === 'string') texts.push(i[k] as string);
  if (name === 'Bash' && typeof i.command === 'string') texts.push(i.command);
  if (name === 'MultiEdit' && typeof i.file_path === 'string') texts.push(i.file_path);
  const out = new Map<string, { slug: string; worktree: string | null }>();
  const esc = root.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`${esc}/(?:\\.branches/([a-z0-9][a-z0-9-]{0,47})/([a-z0-9][a-z0-9_-]{0,63})|([a-z0-9][a-z0-9-]{0,47}))(?=/|$|[\\s'"\`;)&|])`, 'g');
  for (const t of texts) {
    let m: RegExpExecArray | null;
    while ((m = re.exec(t))) {
      const slug = (m[1] ?? m[3])!;
      const worktree = m[1] ? m[2]! : null;
      out.set(`${slug}|${worktree ?? ''}`, { slug, worktree });
    }
  }
  return [...out.values()];
}

/** Is this tool call a (likely) write? Used to light up strands only for edits, not reads. */
export function isWriteTool(name: string, input: unknown): boolean {
  if (['Write', 'Edit', 'MultiEdit', 'NotebookEdit'].includes(name)) return true;
  if (name !== 'Bash') return false;
  const cmd = String((input as { command?: unknown })?.command ?? '');
  return /(^|[\s;&|])(rm|mv|cp|mkdir|touch|sed\s+-i|tee|npm\s+(i|install|add)|git|chmod|ln)\b|>>?/.test(cmd);
}

