        `INSERT INTO conversations(id, project_id, title, model, mode, created_by, created_at, updated_at, scope) VALUES (?, NULL, ?,?,?,?,?,?, 'nexus')`,
      ).run(id, body.title || DEFAULT_TITLE, body.model ?? defaultNexusModel(ctx), body.mode ?? 'auto', u.id, t, t);
