        const p = db.prepare(`SELECT * FROM projects WHERE slug = ?`).get(h.project) as ProjectRow | undefined;
        if (!p) throw notFound('Project not found');
        const { project } = requireProject(db, u, p.id, 'editor');
        if (project.archived) throw conflict('Project is archived', 'archived');
        const branch = h.branch ? getBranch(db, project.id, h.branch) : null;
        if (h.branch && !branch) throw conflict(`Branch "${h.branch}" no longer exists`, 'branch_closed');
        const t = now();
        const convId = crypto.randomUUID();
        db.prepare(
