        ).run(convId, project.id, autoTitle(h.prompt), opts.model ?? run.model, opts.mode ?? 'auto', u.id, t, t, branch?.name ?? null);
        const conv = db.prepare(`SELECT * FROM conversations WHERE id = ?`).get(convId) as ConversationRow & { project_id: string };
        try {
