import { api, createUser, login, makeEnv, openWs, waitFor, type TestEnv } from './helpers.js';
import {
  buildNexusIndex, buildNexusSystemPrompt, INDEX_MAX_CHARS, nexusRunSpec, nexusScope, parseHandoffs, resolveFocus, touchedPaths, type NexusScope,
  type ScopeProject,
} from '../src/lib/nexus.js';
import { visibleText, finalContent } from '../src/lib/suggestions.js';
import type { ProjectRow } from '../src/auth.js';

let env: TestEnv;
let admin: string, alice: string, bob: string;
let aliceId: string, bobId: string;
let pA: any, pB: any, pV: any, pX: any;

const db = () => env.built.ctx.db;
const gitLog = (slug: string) => {
  // read commit messages via the fake claudebox's real git layer
  return env.built.ctx.cb.git<{ commits: { sha: string; message: string }[] }>('history', { projectSlug: slug, limit: 20 });
};
async function gitReady(projectId: string) {
  await waitFor(() => (db().prepare(`SELECT git_main FROM projects WHERE id = ?`).get(projectId) as { git_main: string | null }).git_main, 10000);
}
async function runDone(runId: string) {
  return waitFor(() => {
    const r = db().prepare(`SELECT status, nexus_scope FROM runs WHERE id = ?`).get(runId) as { status: string; nexus_scope: string | null };
    return r.status !== 'queued' && r.status !== 'running' && r.nexus_scope && JSON.parse(r.nexus_scope).checkpointed ? r : null;
  }, 10000);
}

beforeAll(async () => {
  env = await makeEnv({}, { listen: true });
  aliceId = await createUser(env, 'alice@test.local', 'alice-pass');
  bobId = await createUser(env, 'bob@test.local', 'bob-pass');
  admin = await login(env, 'admin@test.local', 'admin-password-1');
  alice = await login(env, 'alice@test.local', 'alice-pass');
  bob = await login(env, 'bob@test.local', 'bob-pass');
  // alice: owner of A, editor of B (granted by admin), viewer of V; X is admin-only
  pA = (await api(env, alice, 'POST', '/api/projects', { name: 'Alpha', description: 'The alpha site' })).json;
  pB = (await api(env, admin, 'POST', '/api/projects', { name: 'Beta' })).json;
  pV = (await api(env, admin, 'POST', '/api/projects', { name: 'Viewonly' })).json;
  pX = (await api(env, admin, 'POST', '/api/projects', { name: 'Secret' })).json;
  const adminId = (db().prepare(`SELECT id FROM users WHERE email = 'admin@test.local'`).get() as { id: string }).id;
  await api(env, admin, 'PUT', `/api/projects/${pB.id}/members`, { members: [{ userId: adminId, role: 'owner' }, { userId: aliceId, role: 'editor' }] });
  await api(env, admin, 'PUT', `/api/projects/${pV.id}/members`, { members: [{ userId: adminId, role: 'owner' }, { userId: aliceId, role: 'viewer' }] });
  for (const p of [pA, pB, pV, pX]) await gitReady(p.id);
});
afterAll(async () => {
  await env.close();
});

describe('nexus scope + sandbox groups', () => {
  it('members: editor+ projects only (viewer-only excluded), admins: all; groups/addDirs match', () => {
    const alice = db().prepare(`SELECT * FROM users WHERE id = ?`).get(aliceId) as any;
    const sc = nexusScope(db(), alice);
    expect(sc.projects.map((x) => x.project.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    expect(sc.viewOnly).toBe(1);
    const spec = nexusRunSpec(env.cfg, 30001, sc, []);
    const gids = sc.projects.map((x) => 20000 + x.project.sandbox_id!);
    expect(spec.sandbox.uid).toBe(30001);
    expect(spec.sandbox.groups.sort()).toEqual([30001, ...gids].sort());
    // never the viewer-only / foreign projects' gids
    for (const p of [pV, pX]) {
      const sid = (db().prepare(`SELECT sandbox_id FROM projects WHERE id = ?`).get(p.id) as { sandbox_id: number }).sandbox_id;
      expect(spec.sandbox.groups).not.toContain(20000 + sid);
    }
    expect(spec.addDirs.sort()).toEqual([`/workspace/projects/${pA.slug}`, `/workspace/projects/${pB.slug}`].sort());
    expect(spec.cwd).toBe('/workspace/.nexus/30001');
    const adm = db().prepare(`SELECT * FROM users WHERE email = 'admin@test.local'`).get() as any;
    expect(nexusScope(db(), adm).projects.length).toBe(4);
    // bob: nothing
    const b = db().prepare(`SELECT * FROM users WHERE id = ?`).get(bobId) as any;
    expect(nexusScope(db(), b).projects).toEqual([]);
  });

  it('focus resolves #slug and #slug@branch within scope only', () => {
    const alice = db().prepare(`SELECT * FROM users WHERE id = ?`).get(aliceId) as any;
    const sc = nexusScope(db(), alice);
    expect(resolveFocus(sc, [pA.slug]).items.map((x) => x.sp.project.slug)).toEqual([pA.slug]);
    expect(resolveFocus(sc, [`#${pV.slug}`, pX.slug, `${pA.slug}@nope`]).errors).toEqual([`#${pV.slug}`, `#${pX.slug}`, `#${pA.slug}@nope`]);
  });
});

describe('nexus index builder', () => {
  const mk = (i: number, desc = 'A fairly long description of what this project does and why it exists, with details.'): ScopeProject => ({
    project: {
      id: `id${i}`, slug: `project-number-${i}`, name: `Project number ${i}`, description: desc, color: '#ff3e8a', icon: 'box', preview_port: 4100 + i,
      preview_command: null, preview_strip: 0, links: '[]', created_by: null, created_at: 0, last_active_at: Date.now() - i * 3600_000, archived: 0,
      parent_id: null, git_main: 'main', sandbox_id: i + 1,
    } as ProjectRow,
    role: 'admin', branches: [], busy: false,
  });
  const opts = { cfg: { projectsDir: '/nope', claudeboxProjectsDir: '/workspace/projects', publicUrl: 'https://ws.example' }, tech: () => 'React+Vite', listing: () => 'index.html, src/' };

  it('stays under the ~1.5k token cap and degrades gracefully', () => {
    for (const n of [1, 5, 20, 60, 200, 900]) {
      const scope: NexusScope = { projects: Array.from({ length: n }, (_, i) => mk(i)), viewOnly: 0 };
      const s = buildNexusIndex(scope, [], opts);
      expect(s.length).toBeLessThanOrEqual(INDEX_MAX_CHARS);
      expect(s).toContain('project-number-0');
      if (n <= 20) expect(s).toContain('A fairly long description');
      if (n >= 200) expect(s).toMatch(/more \(ask the user to #mention/);
    }
  });

  it('focused projects get a detail block (dir, files, preview); others one line', () => {
    const scope: NexusScope = { projects: [mk(1), mk(2), mk(3)], viewOnly: 0 };
    scope.projects[1]!.branches = [{ id: 'b', project_id: 'id2', name: 'feature/x', dir: 'feature_x', base: 'main', preview_port: 4150 } as any];
    const f = resolveFocus(scope, ['project-number-2@feature/x']);
    expect(f.errors).toEqual([]);
    const s = buildNexusIndex(scope, f.items, opts);
    expect(s).toContain('FOCUS');
    expect(s).toContain('dir: /workspace/projects/.branches/project-number-2/feature_x');
    expect(s).toContain('files: index.html, src/');
    expect(s).toContain('preview: https://ws.example/preview/project-number-2--feature_x/');
    expect(s).toMatch(/- project-number-1 "Project number 1"/);
    const sp = buildNexusSystemPrompt(s, '/workspace/.nexus/30001', 2);
    expect(sp).toContain('<nx-handoff>');
    expect(sp).toContain('2 view-only projects are not available');
    expect(sp.length).toBeLessThan(INDEX_MAX_CHARS + 4000);
  });
});

describe('handoff parsing + hidden blocks', () => {
  it('parses the last valid block, filters unknown projects, caps at 4', () => {
    const slugs = new Set(['a', 'b']);
    const t = 'Done.\n<nx-handoff>[{"project":"a","branch":null,"prompt":"do A"},{"project":"zzz","prompt":"x"},{"project":"b","branch":"feature/y","prompt":"do B"},{"project":"a","prompt":"dup"}]</nx-handoff>\n<nx-suggestions>[]</nx-suggestions>';
    expect(parseHandoffs(t, slugs)).toEqual([
      { project: 'a', branch: null, prompt: 'do A' },
      { project: 'b', branch: 'feature/y', prompt: 'do B' },
    ]);
    expect(parseHandoffs('<nx-handoff>not json</nx-handoff>', slugs)).toEqual([]);
    expect(parseHandoffs('```\n<nx-handoff>```json\n{"project":"a","prompt":"single"}\n```</nx-handoff>', slugs)).toEqual([{ project: 'a', branch: null, prompt: 'single' }]);
    expect(finalContent(t)).toBe('Done.');
    expect(visibleText('Hello <nx-hand', true)).toBe('Hello ');
    expect(visibleText('Hello <nx-handoff>[', true)).toBe('Hello ');
  });

  it('maps tool calls to touched project checkouts', () => {
    expect(touchedPaths('/workspace/projects', 'Write', { file_path: '/workspace/projects/alpha/index.html' })).toEqual([{ slug: 'alpha', worktree: null }]);
    expect(touchedPaths('/workspace/projects', 'Edit', { file_path: '/workspace/projects/.branches/alpha/feature_x/a.js' })).toEqual([{ slug: 'alpha', worktree: 'feature_x' }]);
    expect(touchedPaths('/workspace/projects', 'Bash', { command: 'cd /workspace/projects/beta && rm x; cp a /workspace/projects/gamma/b' }).map((x) => x.slug)).toEqual(['beta', 'gamma']);
    expect(touchedPaths('/workspace/projects', 'Read', { file_path: '/etc/passwd' })).toEqual([]);
  });
});

describe('nexus conversations + runs', () => {
  let conv: any;
  it('creates private nexus conversations (sonnet by default)', async () => {
    const r = await api(env, alice, 'POST', '/api/nexus/conversations', {});
    expect(r.status).toBe(201);
    conv = r.json;
    expect(conv).toMatchObject({ scope: 'nexus', projectId: null, model: 'sonnet' });
    expect((await api(env, alice, 'GET', '/api/nexus/conversations')).json.map((c: any) => c.id)).toEqual([conv.id]);
    // private: other users (even admins) get 404 and don't list it
    expect((await api(env, bob, 'GET', `/api/conversations/${conv.id}`)).status).toBe(404);
    expect((await api(env, admin, 'GET', `/api/conversations/${conv.id}/messages`)).status).toBe(404);
    expect((await api(env, bob, 'GET', '/api/nexus/conversations')).json).toEqual([]);
    expect((await api(env, alice, 'PATCH', `/api/conversations/${conv.id}`, { title: 'Cross-site' })).json.title).toBe('Cross-site');
    expect((await api(env, alice, 'PATCH', `/api/conversations/${conv.id}`, { agentSlug: 'researcher' })).status).toBe(400);
    const scope = (await api(env, alice, 'GET', '/api/nexus/scope')).json;
    expect(scope.projects.map((p: any) => p.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    expect(scope.viewOnly).toBe(1);
  });

  let runId: string;
  it('runs with the multi-project sandbox, checkpoints every changed project, parses handoffs', async () => {
    const { ws, msgs } = await openWs(env, alice);
    // a pending edit in B must NOT end up in the nexus checkpoint (pre-run checkpoint)
    fs.writeFileSync(path.join(env.cfg.projectsDir, pB.slug, 'pending.txt'), 'user edit\n');
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, {
      text: `Sync the footer [ntouch:${pA.slug}/footer.html] [ntouch:${pB.slug}/footer.html] [ntouch:${pV.slug}/footer.html] [handoff:${pA.slug}]`,
      projects: [pA.slug],
    });
    expect(r.status).toBe(200);
    runId = r.json.runId;
    expect(r.json.scope).toEqual({ projects: 2, focus: [pA.slug] });
    const body = env.fake.bodies.find((b) => b.runId === runId)!;
    const sids = [pA, pB].map((p) => 20000 + (db().prepare(`SELECT sandbox_id FROM projects WHERE id = ?`).get(p.id) as { sandbox_id: number }).sandbox_id);
    expect(body.sandbox).toMatchObject({ uid: 30001, gid: 30001, home: '/workspace/.sandbox-homes/30001' });
    expect((body.sandbox as any).groups.sort()).toEqual([30001, ...sids].sort());
    expect(body.cwd).toBe('/workspace/.nexus/30001');
    expect((body.addDirs as string[]).sort()).toEqual([`/workspace/projects/${pA.slug}`, `/workspace/projects/${pB.slug}`].sort());
    expect(body.previewPort).toBeUndefined();
    expect(String(body.appendSystemPrompt)).toContain(`## ${pA.slug}`);
    expect(String(body.appendSystemPrompt)).not.toContain(pV.slug);
    expect(String(body.appendSystemPrompt)).not.toContain(pX.slug);
    expect(body.agents).toBeUndefined();

    await runDone(runId);
    // viewer-only project untouched (not in addDirs)
    expect(fs.existsSync(path.join(env.cfg.projectsDir, pV.slug, 'footer.html'))).toBe(false);
    const commits = db().prepare(`SELECT project_id, sha, files FROM nexus_run_commits WHERE run_id = ? ORDER BY project_id`).all(runId) as any[];
    expect(commits.map((c) => c.project_id).sort()).toEqual([pA.id, pB.id].sort());
    const logB = await gitLog(pB.slug);
    expect(logB.commits[0]!.message).toMatch(/^nxeon \(nexus\): Sync the footer/);
    expect(logB.commits[1]!.message).toBe('nxeon: edits before run');
    // per-project commit contains only the run's file
    expect(commits.find((c) => c.project_id === pB.id).files).toBe(1);

    // live events: touched + owner-only status + nexus_run summary
    await waitFor(() => msgs.find((m) => m.t === 'nexus_run' && m.runId === runId), 5000);
    const nx = msgs.find((m) => m.t === 'nexus_run' && m.runId === runId);
    expect(nx.commits.map((c: any) => c.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    expect(nx.handoffs).toEqual([{ project: pA.slug, branch: null, prompt: 'Build the big feature [touch:handoff.txt]' }]);
    expect(msgs.some((m) => m.t === 'run_status' && m.runId === runId && m.projectId === null && m.nexus)).toBe(true);
    expect(msgs.some((m) => m.t === 'graph_pulse' && m.source === 'nexus' && m.projectId === pA.id)).toBe(true);
    ws.close();

    const mm = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    const asst = mm.find((m: any) => m.role === 'assistant');
    expect(asst.content).not.toContain('nx-handoff');
    expect(asst.handoffs).toHaveLength(1);
    expect(asst.nexusCommits.map((c: any) => c.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    expect(asst.events.some((e: any) => e.type === 'nexus' && e.data.touched.includes(pA.id))).toBe(true);
    expect(asst.run.nexus).toMatchObject({ focus: [pA.slug], checkpointed: true });
    // other users can't subscribe to the run
    const bobWs = await openWs(env, bob);
    bobWs.ws.send(JSON.stringify({ t: 'sub', runId }));
    await waitFor(() => bobWs.msgs.find((m) => m.t === 'error'), 3000);
    expect(bobWs.msgs.some((m) => m.t === 'run_event')).toBe(false);
    bobWs.ws.close();
  });

  it('rejects focus outside the scope', async () => {
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'hi', projects: [pX.slug] });
    expect(r.status).toBe(400);
    expect(r.json.error.code).toBe('unknown_focus');
  });

  it('sends a handoff as a background project conversation (once)', async () => {
    const r = await api(env, alice, 'POST', `/api/runs/${runId}/handoffs/0`, {});
    expect(r.status).toBe(200);
    expect(r.json).toMatchObject({ projectId: pA.id, projectSlug: pA.slug });
    expect(r.json.conversation).toMatchObject({ projectId: pA.id, scope: 'project', model: 'sonnet' });
    expect(r.json.handoffs[0].sent.runId).toBe(r.json.runId);
    await waitFor(() => (db().prepare(`SELECT status FROM runs WHERE id = ?`).get(r.json.runId) as { status: string }).status === 'done', 5000);
    expect((await api(env, alice, 'POST', `/api/runs/${runId}/handoffs/0`, {})).status).toBe(409);
    expect((await api(env, bob, 'POST', `/api/runs/${runId}/handoffs/0`, {})).status).toBe(404);
  });

  it('"Undo this run" reverts the checkpoint in every touched project', async () => {
    expect((await api(env, bob, 'POST', `/api/runs/${runId}/undo`)).status).toBe(404);
    // wait for the handoff run's own checkpoint in A
    await waitFor(() => fs.existsSync(path.join(env.cfg.projectsDir, pA.slug, 'handoff.txt')), 5000);
    await new Promise((r) => setTimeout(r, 300));
    const r = await api(env, alice, 'POST', `/api/runs/${runId}/undo`);
    expect(r.status).toBe(200);
    expect(r.json.ok).toBe(true);
    expect(r.json.results.map((x: any) => x.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    for (const p of [pA, pB]) expect(fs.existsSync(path.join(env.cfg.projectsDir, p.slug, 'footer.html'))).toBe(false);
    // user edit committed before the run survives; the later handoff run's file too
    expect(fs.existsSync(path.join(env.cfg.projectsDir, pB.slug, 'pending.txt'))).toBe(true);
    expect(fs.existsSync(path.join(env.cfg.projectsDir, pA.slug, 'handoff.txt'))).toBe(true);
    const mm = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(mm.find((m: any) => m.role === 'assistant').nexusCommits.every((c: any) => c.undone)).toBe(true);
    expect((await api(env, alice, 'POST', `/api/runs/${runId}/undo`)).status).toBe(409);
  });

  it('permissions are recomputed per run (revoked project leaves the scope)', async () => {
    const adminId = (db().prepare(`SELECT id FROM users WHERE email = 'admin@test.local'`).get() as { id: string }).id;
    await api(env, admin, 'PUT', `/api/projects/${pB.id}/members`, { members: [{ userId: adminId, role: 'owner' }] });
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'ask only', mode: 'ask' });
    expect(r.status).toBe(200);
    const body = env.fake.bodies.find((b) => b.runId === r.json.runId)!;
    expect(body.addDirs).toEqual([`/workspace/projects/${pA.slug}`]);
    expect((body.sandbox as any).groups).toHaveLength(2);
    await runDone(r.json.runId);
    expect(db().prepare(`SELECT COUNT(*) AS n FROM nexus_run_commits WHERE run_id = ?`).get(r.json.runId)).toEqual({ n: 0 });
  });

  it('compact works for nexus conversations; deleting removes it', async () => {
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/compact`, {});
    expect(r.status).toBe(200);
    const body = env.fake.bodies.find((b) => b.runId === r.json.runId)!;
    expect(body.prompt).toBe('/compact');
    expect(body.cwd).toBe('/workspace/.nexus/30001');
    expect(body.sessionId).toBe('sess-1');
    await waitFor(() => (db().prepare(`SELECT status FROM runs WHERE id = ?`).get(r.json.runId) as { status: string }).status === 'done', 5000);
    expect((await api(env, bob, 'DELETE', `/api/conversations/${conv.id}`)).status).toBe(404);
    expect((await api(env, alice, 'DELETE', `/api/conversations/${conv.id}`)).status).toBe(200);
    expect((await api(env, alice, 'GET', '/api/nexus/conversations')).json).toEqual([]);
  });

  it('nexus identities are per user and never reused', async () => {
    const c = (await api(env, admin, 'POST', '/api/nexus/conversations', {})).json;
    const r = await api(env, admin, 'POST', `/api/conversations/${c.id}/prompt`, { text: 'hello', mode: 'ask' });
    const body = env.fake.bodies.find((b) => b.runId === r.json.runId)!;
    expect((body.sandbox as any).uid).toBe(30002);
    expect(body.cwd).toBe('/workspace/.nexus/30002');
    expect((body.sandbox as any).groups).toHaveLength(5);
    await runDone(r.json.runId);
  });
});

