  let runId: string;
  it('runs with the multi-project sandbox, checkpoints every changed project, parses handoffs', async () => {
    const { ws, msgs } = await openWs(env, alice);
    // a pending edit in B must NOT end up in the nexus checkpoint (pre-run checkpoint)
