    const commits = db().prepare(`SELECT project_id, sha, files FROM nexus_run_commits WHERE run_id = ? ORDER BY project_id`).all(runId) as any[];
    expect(commits.map((c) => c.project_id).sort()).toEqual([pA.id, pB.id].sort());
    const logB = await gitLog(pB.slug);
