  it('"Undo this run" reverts the checkpoint in every touched project', async () => {
    expect((await api(env, bob, 'POST', `/api/runs/${runId}/undo`)).status).toBe(404);
    // wait for the handoff run's own checkpoint in A
    await waitFor(() => fs.existsSync(path.join(env.cfg.projectsDir, pA.slug, 'handoff.txt')), 5000);
    await new Promise((r) => setTimeout(r, 300));
    const r = await api(env, alice, 'POST', `/api/runs/${runId}/undo`);
    expect(r.status).toBe(200);
    expect(r.json.ok).toBe(true);
    expect(r.json.results.map((x: any) => x.slug).sort()).toEqual([pA.slug, pB.slug].sort());
    for (const p of [pA, pB]) expect(fs.existsSync(path.join(env.cfg.projectsDir, p.slug, 'footer.html'))).toBe(false);
    // user edit committed before the run survives; the later handoff run's file too
    expect(fs.existsSync(path.join(env.cfg.projectsDir, pB.slug, 'pending.txt'))).toBe(true);
    expect(fs.existsSync(path.join(env.cfg.projectsDir, pA.slug, 'handoff.txt'))).toBe(true);
    const mm = (await api(env, alice, 'GET', `/api/conversations/${conv.id}/messages`)).json;
    expect(mm.find((m: any) => m.role === 'assistant').nexusCommits.every((c: any) => c.undone)).toBe(true);
    expect((await api(env, alice, 'POST', `/api/runs/${runId}/undo`)).status).toBe(409);
  });

  it('permissions are recomputed per run (revoked project leaves the scope)', async () => {
    const adminId = (db().prepare(`SELECT id FROM users WHERE email = 'admin@test.local'`).get() as { id: string }).id;
    await api(env, admin, 'PUT', `/api/projects/${pB.id}/members`, { members: [{ userId: adminId, role: 'owner' }] });
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/prompt`, { text: 'ask only', mode: 'ask' });
    expect(r.status).toBe(200);
    const body = env.fake.bodies.find((b) => b.runId === r.json.runId)!;
    expect(body.addDirs).toEqual([`/workspace/projects/${pA.slug}`]);
    expect((body.sandbox as any).groups).toHaveLength(2);
    await runDone(r.json.runId);
    expect(db().prepare(`SELECT COUNT(*) AS n FROM nexus_run_commits WHERE run_id = ?`).get(r.json.runId)).toEqual({ n: 0 });
  });

  it('compact works for nexus conversations; deleting removes it', async () => {
    const r = await api(env, alice, 'POST', `/api/conversations/${conv.id}/compact`, {});
    expect(r.status).toBe(200);
    const body = env.fake.bodies.find((b) => b.runId === r.json.runId)!;
    expect(body.prompt).toBe('/compact');
