#!/bin/bash
# Test double for `sudo -n /usr/local/sbin/nx-sandbox <op> ...`: performs the same argument/env-file
# protocol WITHOUT switching uid, and logs every helper call to $FAKE_SUDO_LOG (one JSON-ish line each).
set -u
[ "$1" = "-n" ] && shift
shift # wrapper path
op=$1; shift
echo "$op $*" >>"${FAKE_SUDO_LOG:-/dev/null}"
case "$op" in
  exec)
    uid="" cwd="" envfile=""
    while [ $# -gt 0 ]; do
      case "$1" in
        --uid) uid=$2; shift 2 ;;
        --gid|--groups|--setenv) shift 2 ;;
        --cwd) cwd=$2; shift 2 ;;
        --env-file) envfile=$2; shift 2 ;;
        --) shift; break ;;
        *) echo "fake-sudo: bad arg $1" >&2; exit 2 ;;
      esac
    done
    envs=()
    while IFS= read -r -d '' kv; do envs+=("$kv"); done <"$envfile"
    rm -f "$envfile"
    home="${FAKE_HOMES:?}/$uid"
    mkdir -p "$home/tmp"
    exec env -i -C "$cwd" "PATH=/usr/local/bin:/usr/bin:/bin" "${envs[@]}" "HOME=$home" "CLAUDE_CONFIG_DIR=$home/.claude" "TMPDIR=$home/tmp" "FAKE_SANDBOX_UID=$uid" "$@"
    ;;
  kill)
    pgid="" sig=TERM
    while [ $# -gt 0 ]; do case "$1" in --pgid) pgid=$2; shift 2 ;; --signal) sig=$2; shift 2 ;; *) shift 2 ;; esac; done
    kill -s "$sig" -- "-$pgid" 2>/dev/null || true
    ;;
  kill-port) echo 0 ;;
  setup|home) echo '{"ok":true,"heavy":false}' ;;
  fixperms|net-claim) echo ok ;;
  *) echo "fake-sudo: unknown op $op" >&2; exit 2 ;;
esac
"use strict";
// Sandbox plumbing tests. Real uid switching needs root + /usr/local/sbin/nx-sandbox (see
// sandbox/redteam.sh for the in-container checks); here a fake `sudo` (test/fake-sudo.sh) speaks the same
// helper protocol without changing uid, so argv/env-file/stdin/attachment handling is verified end to end.
const assert = require("node:assert/strict");
const test = require("node:test");
const fs = require("fs");
const os = require("os");
const path = require("path");

const { Sandbox, ENV_DROP } = require("../lib/sandbox");
const { RunManager, buildRunArgs } = require("../lib/runs");
const { PreviewManager } = require("../lib/preview");

const MOCK = path.join(__dirname, "mock-claude.js");
const FAKE_SUDO = path.join(__dirname, "fake-sudo.sh");
fs.chmodSync(MOCK, 0o755);
fs.chmodSync(FAKE_SUDO, 0o755);

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "claudebox-sandbox-"));
const PROJECTS = path.join(TMP, "projects");
const HOMES = path.join(TMP, "homes");
const UPLOADS = path.join(TMP, "private", "uploads");
const ENVDIR = path.join(TMP, "envs");
const LOG = path.join(TMP, "helper.log");
const ARGS_FILE = path.join(TMP, "args.json");
for (const d of [path.join(PROJECTS, "alpha"), path.join(UPLOADS, "up1"), HOMES]) fs.mkdirSync(d, { recursive: true });
fs.writeFileSync(path.join(UPLOADS, "up1", "notes.txt"), "secret notes");
const sb = new Sandbox({ mode: "strict", sudo: FAKE_SUDO, helperEnv: { FAKE_HOMES: HOMES, FAKE_SUDO_LOG: LOG }, wrapper: "/usr/bin/env", projectsDir: PROJECTS, homesDir: HOMES, envDir: ENVDIR, nexusDir: path.join(TMP, "nexus") });
const SPEC = { uid: 20007, gid: 20007, groups: [20007], home: path.join(HOMES, "20007") };
fs.mkdirSync(SPEC.home, { recursive: true });

const helperLog = () => (fs.existsSync(LOG) ? fs.readFileSync(LOG, "utf8") : "");
const waitFor = async (fn, ms = 8000) => {
  const end = Date.now() + ms;
  for (;;) {
    const v = await fn();
    if (v) return v;
    if (Date.now() > end) throw new Error("timeout");
    await new Promise((r) => setTimeout(r, 25));
  }
};

test("validateSpec: ranges, gid == uid, home bound to uid, groups", () => {
  assert.deepEqual(sb.validateSpec({ uid: 20007 }).spec, SPEC);
  assert.deepEqual(sb.validateSpec({ uid: 30001, gid: 30001, groups: [20001, 20002, 20001] }).spec.groups, [30001, 20001, 20002]);
  assert.match(sb.validateSpec({ uid: 1000 }).error, /uid/);
  assert.match(sb.validateSpec({ uid: 0 }).error, /uid/);
  assert.match(sb.validateSpec({ uid: 20001, gid: 20002 }).error, /gid must equal/);
  assert.match(sb.validateSpec({ uid: 20001, groups: [1000] }).error, /group/);
  assert.match(sb.validateSpec({ uid: 20001, groups: new Array(65).fill(20002) }).error, /groups/);
  assert.match(sb.validateSpec({ uid: 20001, home: "/workspace/.sandbox-homes/20002" }).error, /home/);
  assert.equal(sb.validateSpec(null).spec, null);
  assert.equal(sb.specFromDir("alpha"), null); // dir group 1000 is not a sandbox group
  assert.throws(() => sb.resolveProject("alpha", { uid: 30001 }), /project sandbox uid/);
});

test("childEnv strips server-only vars but keeps the run's auth", () => {
  const e = sb.childEnv({ CLAUDEBOX_API_KEY: "k", HOME: "/home/claude", PATH: "/x", CLAUDE_CONFIG_DIR: "/home/claude/.claude", CLAUDE_CODE_OAUTH_TOKEN: "tok", PORT: "4100", "BAD-KEY": "x", NUL: "a\0b" });
  assert.deepEqual(e, { CLAUDE_CODE_OAUTH_TOKEN: "tok", PORT: "4100" });
  for (const k of ["CLAUDEBOX_API_KEY", "HOME", "PATH", "CLAUDE_CONFIG_DIR", "NPM_CONFIG_PREFIX"]) assert.ok(ENV_DROP.has(k));
});

test("command(): strict mode goes through `sudo -n nx-sandbox exec` with a private env file (no secrets in argv)", () => {
  const c = sb.command({ ...SPEC, groups: [20007, 20009] }, "/workspace/projects/alpha", "claude", ["-p"], { CLAUDE_CODE_OAUTH_TOKEN: "sk-ant-oat01-secret", X: "1" });
  assert.equal(c.bin, FAKE_SUDO);
  assert.deepEqual(c.args.slice(0, 10), ["-n", "/usr/bin/env", "exec", "--uid", "20007", "--gid", "20007", "--groups", "20007,20009", "--cwd"]);
  assert.ok(!c.args.join(" ").includes("secret"));
  assert.deepEqual(Object.keys(c.env).sort(), ["FAKE_HOMES", "FAKE_SUDO_LOG", "PATH"]);
  const st = fs.statSync(c.envFile);
  assert.equal(st.mode & 0o777, 0o600);
  assert.equal(fs.readFileSync(c.envFile, "utf8"), "CLAUDE_CODE_OAUTH_TOKEN=sk-ant-oat01-secret\0X=1\0");
  fs.rmSync(c.envFile);
  // off mode: direct spawn, but sessions still live in the project's home when it exists
  const off = new Sandbox({ mode: "off", homesDir: HOMES });
  const o = off.command(SPEC, "/w", "claude", ["-p"], { HOME: "/home/claude" });
  assert.equal(o.bin, "claude");
  assert.equal(o.env.HOME, SPEC.home);
  assert.equal(o.env.CLAUDE_CONFIG_DIR, path.join(SPEC.home, ".claude"));
});
