test("buildRunArgs: stdin prompt + system prompt file + explicit add-dirs", () => {
  const args = buildRunArgs({ prompt: "hi", promptViaStdin: true, appendSystemPromptFile: "/h/sp.md", appendSystemPrompt: "x", addDirsResolved: ["/h/uploads"] }, {}, { uploadsDir: "/u" });
  assert.ok(!args.includes("--"));
  assert.ok(!args.includes("hi"));
  assert.deepEqual(args.slice(args.indexOf("--append-system-prompt-file"), args.indexOf("--append-system-prompt-file") + 2), ["--append-system-prompt-file", "/h/sp.md"]);
