  assert.deepEqual(args.filter((a, i) => args[i - 1] === "--add-dir"), ["/h/uploads"]);
});

test("validate: sandbox spec, Nexus cwd and addDirs are checked", () => {
  const runs = new RunManager({ claudeBin: MOCK, projectsDir: PROJECTS, uploadsDir: UPLOADS, sandbox: sb });
  const base = { prompt: "x", projectSlug: "alpha" };
  assert.match(runs.validate(base).error, /sandbox is not set up/);
  assert.equal(runs.validate({ ...base, sandbox: { uid: 20007 } }).opts.sandbox.uid, 20007);
  assert.match(runs.validate({ ...base, sandbox: { uid: 99 } }).error, /uid/);
  assert.match(runs.validate({ ...base, cwd: path.join(TMP, "nexus", "u1") }).error, /requires a sandbox/);
  const nx = { ...base, sandbox: { uid: 30001, groups: [20007] } };
  assert.match(runs.validate({ ...nx, cwd: "/etc" }).error, /cwd must be inside/);
  assert.match(runs.validate({ ...nx, cwd: path.join(TMP, "nexus", "..", "projects") }).error, /cwd must be inside/);
  const ok = runs.validate({ ...nx, cwd: path.join(TMP, "nexus", "u1"), addDirs: [path.join(PROJECTS, "alpha")] });
  assert.equal(ok.error, undefined);
  assert.equal(ok.opts.nexus, true);
  assert.deepEqual(ok.opts.addDirs, [path.join(PROJECTS, "alpha")]);
  assert.match(runs.validate({ ...nx, cwd: path.join(TMP, "nexus", "u1"), addDirs: ["/etc"] }).error, /project dirs/);
  assert.match(runs.validate({ ...nx, cwd: path.join(TMP, "nexus", "u1"), addDirs: [path.join(PROJECTS, ".trash", "x")] }).error, /project dirs/);
  runs.close();
});

test("strict run: helper exec, prompt via stdin, attachments copied into the sandbox home, cleanup + fixperms", async () => {
  fs.writeFileSync(LOG, "");
  const runs = new RunManager({ claudeBin: MOCK, projectsDir: PROJECTS, uploadsDir: UPLOADS, sandbox: sb, env: { ...process.env, MOCK_ARGS_FILE: ARGS_FILE, CLAUDE_CODE_OAUTH_TOKEN: "tok-123", CLAUDEBOX_API_KEY: "server-key" } });
  const { opts, error } = runs.validate({
    runId: "run-sb-1", prompt: "build it", projectSlug: "alpha", sandbox: { uid: 20007 }, previewPort: 4105,
    attachments: [path.join(UPLOADS, "up1", "notes.txt")], appendSystemPrompt: "SYSTEM SECRET",
    agents: { helper: { description: "d", prompt: "p" } },
  });
  assert.equal(error, undefined);
  const run = runs.create(opts);
  await waitFor(() => run.finished);
  assert.equal(run.status, "done");
  const got = JSON.parse(fs.readFileSync(ARGS_FILE, "utf8"));
  const copied = path.join(SPEC.home, "uploads", "up1", "notes.txt");
  assert.equal(fs.readFileSync(copied, "utf8"), "secret notes");
  assert.match(got.prompt, /^build it\n\n\[Attached file: .*homes\/20007\/uploads\/up1\/notes\.txt/);
  assert.ok(!got.args.includes("build it"), "prompt must not be in argv");
  assert.ok(!got.args.includes("SYSTEM SECRET"), "system prompt must not be in argv");
  assert.ok(got.args.includes("--append-system-prompt-file"));
  assert.ok(got.args[got.args.indexOf("--agents") + 1].startsWith(path.join(SPEC.home, ".nxeon", "runs")));
  assert.equal(got.args[got.args.indexOf("--add-dir") + 1], path.join(SPEC.home, "uploads"));
  assert.equal(got.cwd, path.join(PROJECTS, "alpha"));
  assert.equal(got.env.HOME, SPEC.home);
  assert.equal(got.env.FAKE_SANDBOX_UID, "20007");
  assert.equal(got.env.CLAUDE_CODE_OAUTH_TOKEN, "tok-123");
  assert.equal(got.env.CLAUDEBOX_API_KEY, undefined);
  assert.equal(got.env.PORT, "4105");
  // per-run files are removed, env files are consumed
  await waitFor(() => !fs.existsSync(path.join(SPEC.home, ".nxeon", "runs", "run-sb-1")));
  assert.deepEqual(fs.readdirSync(ENVDIR), []);
  const log = await waitFor(() => (helperLog().includes("fixperms") ? helperLog() : null));
  assert.match(log, /^exec --uid 20007 --gid 20007 --cwd .*alpha --env-file /m);
  assert.match(log, /^net-claim --port 4105 --uids 20007$/m);
  assert.match(log, /^fixperms --uid 20007 --slug alpha$/m);
  assert.equal(runs.info(run).sandboxUid, 20007);
  runs.close();
});

test("strict abort: the helper signals the sandbox uid's process group", async () => {
  fs.writeFileSync(LOG, "");
  const runs = new RunManager({ claudeBin: MOCK, projectsDir: PROJECTS, uploadsDir: UPLOADS, sandbox: sb, killGraceMs: 500, env: { ...process.env, MOCK_ARGS_FILE: "" } });
  const run = runs.create(runs.validate({ runId: "run-sb-2", prompt: "SLOW please", projectSlug: "alpha", sandbox: { uid: 20007 } }).opts);
  await waitFor(() => run.events.some((e) => e.type === "init"));
  runs.abort("run-sb-2");
  await waitFor(() => run.finished);
  assert.equal(run.status, "aborted");
  assert.match(helperLog(), new RegExp(`^kill --uid 20007 --pgid ${run.pid} --signal TERM$`, "m"));
  runs.close();
});

test("strict preview: dev server runs through the helper; stop uses helper kill + kill-port", async () => {
  fs.writeFileSync(LOG, "");
  const previews = new PreviewManager({ projectsDir: PROJECTS, portMin: 4100, portMax: 4199, sandbox: sb });
  const port = 4100 + Math.floor(Math.random() * 90);
  const cmd = `node -e "require('http').createServer((q,s)=>s.end('home='+process.env.HOME+' uid='+process.env.FAKE_SANDBOX_UID)).listen(process.env.PORT,'127.0.0.1')"`;
  const r = await previews.start({ projectSlug: "alpha", port, command: cmd, sandbox: SPEC });
  let body;
  try {
    assert.equal(r.status, 200);
    body = await waitFor(async () => {
      try {
        return await (await fetch(`http://127.0.0.1:${port}/`)).text();
      } catch {
        return null;
      }
    });
  } finally {
    var st = await previews.stop({ projectSlug: "alpha", sandbox: SPEC });
  }
  assert.equal(body, `home=${SPEC.home} uid=20007`);
  assert.equal(st.stopped, true);
  const log = helperLog();
  assert.match(log, /^net-claim --port \d+ --uids 20007$/m);
  assert.match(log, /^exec --uid 20007 --gid 20007 --cwd .*alpha --env-file .* -- bash -c /m);
  assert.match(log, /^kill --uid 20007 --pgid \d+ --signal TERM$/m);
  assert.match(log, new RegExp(`^kill-port --uid 20007 --port ${port} --signal TERM`, "m"));
});

