// `#slug` / `#slug@branch` project mentions for Nexus Chat (pure, unit-tested in workspace/reducer.test.mjs).

export interface MentionProject { slug: string; branches: string[] }

const MENTION_RE = /(^|[\s(,;:])#([a-z0-9][a-z0-9-]{0,47})(?:@([a-z0-9][a-z0-9/-]{0,63}))?(?=$|[\s),.;:!?])/g;

/** Focus list (`slug` or `slug@branch`) of the valid mentions in `text`, in order, deduped. `@main` = main checkout. */
export function parseMentions(text: string, projects: MentionProject[]): string[] {
  const out: string[] = [];
  for (const m of text.matchAll(MENTION_RE)) {
    const p = projects.find((x) => x.slug === m[2]);
    if (!p) continue;
    const b = m[3] && m[3] !== 'main' && p.branches.includes(m[3]) ? m[3] : null;
    if (m[3] && m[3] !== 'main' && !b) continue;
    const key = b ? `${p.slug}@${b}` : p.slug;
    if (!out.includes(key)) out.push(key);
  }
  return out;
}

/** The mention being typed at the caret: `#que` → {start (index of '#'), query, branch: null}; `#slug@br` → branch query. */
export function mentionQuery(text: string, caret: number): { start: number; query: string; branch: string | null } | null {
  const m = /(^|[\s(,;:])#([a-z0-9-]{0,48})(?:@([a-z0-9/-]{0,64}))?$/.exec(text.slice(0, caret));
  if (!m) return null;
  const start = caret - m[0].length + m[1].length;
  return { start, query: m[2], branch: m[3] ?? null };
}

/** Text segments for rendering mentions as chips (only valid mentions become chips). */
export function mentionSegments(text: string, projects: MentionProject[]): { text: string; slug?: string; branch?: string | null }[] {
  const segs: { text: string; slug?: string; branch?: string | null }[] = [];
  let i = 0;
  for (const m of text.matchAll(MENTION_RE)) {
    const p = projects.find((x) => x.slug === m[2]);
    if (!p) continue;
    const b = m[3] && m[3] !== 'main' ? (p.branches.includes(m[3]) ? m[3] : undefined) : null;
    if (b === undefined) continue;
    const at = m.index! + m[1].length;
    if (at > i) segs.push({ text: text.slice(i, at) });
    const len = m[0].length - m[1].length;
    segs.push({ text: text.slice(at, at + len), slug: p.slug, branch: b });
    i = at + len;
  }
  if (i < text.length) segs.push({ text: text.slice(i) });
  return segs;
}
