// Project list + graph store (shared by Nexus, command palette, etc).
import { create } from 'zustand';
import { api } from '@/lib/api';
import type { Graph, Project } from '@/lib/types';

export interface NewProjectInput { name: string; description: string; color: string; icon: string; slug?: string; parentId?: string | null }

interface ProjectsState {
  projects: Project[];
  graph: Graph | null;
  loaded: boolean;
  loading: boolean;
  error: string | null;
  load: () => Promise<void>;
  loadGraph: () => Promise<void>;
  create: (p: NewProjectInput) => Promise<Project>;
}

function unwrapList(r: any): Project[] { return Array.isArray(r) ? r : r?.projects ?? r?.items ?? []; }

export const useProjects = create<ProjectsState>((set, get) => ({
  projects: [], graph: null, loaded: false, loading: false, error: null,
  load: async () => {
    set({ loading: true });
    try { const r = await api.get<any>('/projects'); set({ projects: unwrapList(r), loaded: true, error: null }); }
    catch (e: any) { set({ error: e?.message || 'Failed to load projects', loaded: true }); }
    finally { set({ loading: false }); }
  },
  loadGraph: async () => {
    try { const g = await api.get<Graph>('/projects/graph?satellites=1'); set({ graph: { nodes: g.nodes || [], links: g.links || [] } }); }
    catch (e: any) { set({ error: e?.message || 'Failed to load graph' }); }
  },
  create: async (p) => {
    const r = await api.post<any>('/projects', p);
    const proj: Project = r?.project ?? r;
    set({ projects: [proj, ...get().projects.filter((x) => x.id !== proj.id)] });
    get().loadGraph();
    return proj;
  },
}));
