  const [sp, setSp] = useSearchParams();
  const urlBranch = sp.get('branch') || null;
  const storeBranch = useWs((s) => s.branch);
  const user = useAuth((s) => s.user);
  const project = useWs((s) => s.project);
  const projectError = useWs((s) => s.projectError);
  const leftCollapsed = useWs((s) => s.leftCollapsed);
  const rightCollapsed = useWs((s) => s.rightCollapsed);
  const mobileTab = useWs((s) => s.mobileTab);
  const canEdit = useWs((s) => s.canEdit);
  const set = useWs((s) => s.set);
  const isNarrow = useMediaQuery('(max-width: 1023px)');
  const [dragging, setDragging] = useState(false);
  const leftRef = usePanelRef();
  const rightRef = usePanelRef();
  const layout = useDefaultLayout({ id: `nxw-layout-${user?.id ?? 'anon'}`, storage: localStorage });

  // boot
  useEffect(() => {
    try { if (localStorage.getItem('nxDebug') === '1') (window as any).__nxWs = useWs; } catch { /* */ }
    live.connect();
    const offMsg = live.on((m) => useWs.getState().handleServerMsg(m));
    const offStatus = live.onStatus((c) => {
      const was = useWs.getState().connected;
      useWs.getState().setConnected(c);
      if (c && !was) { const s = useWs.getState(); s.refreshTree(); s.refreshPreview(); if (s.activeConvId) s.loadMessages(s.activeConvId, true); }
    });
    useWs.getState().setConnected(live.connected);
    return () => { offMsg(); offStatus(); };
  }, []);
  useEffect(() => {
    useWs.getState().init(slug, urlBranch, sp.get('topic'));
    return () => useWs.getState().reset();
  }, [slug]); // eslint-disable-line react-hooks/exhaustive-deps
  // URL (?branch=) → store
  useEffect(() => {
    const s = useWs.getState();
    if (s.project && (s.branch ?? null) !== urlBranch) {
      if (s.tabs.some((t) => t.content !== t.saved) && !window.confirm('Discard unsaved editor changes and switch branch?')) {
        const next = new URLSearchParams(sp);
        if (s.branch) next.set('branch', s.branch); else next.delete('branch');
        setSp(next, { replace: true });
        return;
      }
      s.switchBranch(urlBranch);

