// The chat components (Chat, AssistantMessage, PromptBox, ContextMeter) read a "chat store" from context.
// Default: the project workspace store. Nexus Chat provides its own store with the same chat surface, so the
// components, the run reducer and the rendering are shared instead of duplicated.
import { createContext, useContext, type ReactNode } from 'react';
import type { MentionProject } from '../nexus/mentions';
import { useWs, type WorkspaceStore } from './store';

export type ChatStore = Pick<
  WorkspaceStore,
  | 'items' | 'runs' | 'itemsLoading' | 'canEdit' | 'retry' | 'activeConvId' | 'project' | 'send' | 'setDraft' | 'prefs' | 'setPrefs'
  | 'models' | 'uploads' | 'draft' | 'sending' | 'sendError' | 'usage' | 'agents' | 'conversations' | 'draftAgent' | 'abort'
  | 'addFiles' | 'removeUpload' | 'newConversation' | 'clearSendError' | 'setRightTab' | 'set' | 'compact' | 'setLeadAgent'
  | 'openFile' | 'tree'
>;

/** A zustand-style hook: `useStore(selector)` + `useStore.getState()`. */
export interface ChatStoreHook {
  <U>(selector: (s: ChatStore) => U): U;
  getState(): ChatStore;
}

export interface MentionOption extends MentionProject {
  name: string;
  color: string;
  description?: string;
  busy?: boolean;
}

/** Optional prompt-box extensions (Nexus: #project mentions, scope info, cost hints). */
export interface PromptAddons {
  mentions?: MentionOption[];
  /** called with the current text (Nexus highlights #mentioned projects on the web while typing) */
  onTextChange?: (text: string) => void;
  /** rendered at the start of the footer's right side (e.g. "12 projects in scope") */
  footerInfo?: ReactNode;
  /** rendered above the box (e.g. a gentle cost warning); receives the current text */
  notice?: (text: string) => ReactNode;
  placeholder?: string;
  hideAgent?: boolean;
  /** slash commands that make no sense here (e.g. preview, files) */
  hideCommands?: string[];
}

export interface ChatContextValue {
  store: ChatStoreHook;
  /** extra content under an assistant message's footer (Nexus: per-project changes, handoffs) */
  renderRunExtras?: (runId: string, live: boolean) => ReactNode;
  emptyState?: ReactNode;
  prompt?: PromptAddons;
  /** narrower content column (e.g. inside the Nexus panel) */
  compact?: boolean;
}

export const ChatCtx = createContext<ChatContextValue>({ store: useWs as unknown as ChatStoreHook });

export const useChatCtx = () => useContext(ChatCtx);
/** The store hook of the surrounding chat (workspace by default). */
export const useChatStore = (): ChatStoreHook => useContext(ChatCtx).store;

