// Nexus Chat store: the chat surface of the workspace store (same field names, same run reducer) for
// user-owned conversations that work across all projects in scope, plus Nexus extras (scope, handoffs, checkpoints).
import { create } from 'zustand';
import { api } from '@/lib/api';
import { live } from '@/lib/ws';
import type { Attachment, Conversation, Message, ModelInfo, NexusScope, StoredEvent, UsageSummary } from '@/lib/types';
import type { NexusCommit, NexusHandoff, RunStatus, ServerMsg } from '@/shared/protocol';
import { applyRunEvent, emptyRun, replay, setStatus, type RunView, type SeqEvent } from '../workspace/reducer';
import { errInfo, isTerminal, toItems, unwrap, type ChatItem, type PendingUpload, type Prefs, type SendError, type WorkspaceStore } from '../workspace/store';
import type { ChatStore } from '../workspace/chatStore';
import { parseMentions } from './mentions';

export interface NexusRunInfo {
  commits: NexusCommit[];
  handoffs: NexusHandoff[];
  checkpointed: boolean;
  focus: string[];
}
/** Live state of a handoff sent from Nexus Chat (a project run in the background). */
export interface HandoffRun { runId: string; projectId: string; slug: string; conversationId: string; status: RunStatus | 'sending' }

interface NexusState extends ChatStore {
  ready: boolean;
  convLoading: boolean;
  scope: NexusScope | null;
  nexusRuns: Record<string, NexusRunInfo>;
  /** `${runId}:${idx}` → background handoff run */
  handoffRuns: Record<string, HandoffRun>;
  undoing: Record<string, boolean>;
  init(): Promise<void>;
  loadScope(): Promise<void>;
  loadConversations(): Promise<void>;
  selectConversation(id: string | null): Promise<void>;
  loadMessages(id: string, silent?: boolean): Promise<void>;
  renameConversation(id: string, title: string): Promise<void>;
  deleteConversation(id: string): Promise<void>;
  handleServerMsg(m: ServerMsg): void;
  sendHandoff(runId: string, idx: number): Promise<void>;
  undoRun(runId: string, projectId?: string): Promise<void>;
  /** project ids being worked on by an active run (for the web) */
  activeRunId(): string | null;
}

const LS_PREFS = 'nx:nexus:prefs';
const LS_CONV = 'nx:nexus:conv';
const DEFAULT_PREFS: Prefs = { model: 'sonnet', mode: 'auto', thinking: 'normal' };
const lsGet = <T,>(k: string, d: T): T => { try { const v = localStorage.getItem(k); return v ? { ...d, ...JSON.parse(v) } : d; } catch { return d; } };

const subscribed = new Set<string>();
function ensureSub(runId: string, fromSeq: number) {
  if (subscribed.has(runId)) return;
  subscribed.add(runId);
  live.subRun(runId, fromSeq);
}
function dropSub(runId: string) {
  if (!subscribed.has(runId)) return;
  subscribed.delete(runId);
  live.unsubRun(runId);
}
let reconcileTimer: number | undefined;

/** /workspace/projects/<slug>/<rel> → a project slug (for "open file" links in Nexus messages). */
export function projectOfPath(p: string): { slug: string; rel: string } | null {
  const m = /^\/workspace\/projects\/(?:\.branches\/)?([a-z0-9][a-z0-9-]{0,47})(?:\/(.*))?$/.exec(p);
  return m ? { slug: m[1], rel: m[2] ?? '' } : null;
}

export const useNexusChat = create<NexusState>((set, get) => {
  const putRun = (runId: string, fn: (r: RunView) => RunView) =>
    set((s) => {
      const cur = s.runs[runId] ?? emptyRun(runId, 'running');
      const next = fn(cur);
      return next === cur ? s : { runs: { ...s.runs, [runId]: next } };
    });
  const scheduleReconcile = () => {
    window.clearTimeout(reconcileTimer);
    reconcileTimer = window.setTimeout(() => {
      const c = get().activeConvId;
      if (c) get().loadMessages(c, true);
      get().loadConversations();
      get().refreshUsage();
    }, 400);
  };
  const ws = {} as WorkspaceStore; // only for the `set` signature below

  const store: NexusState = {
    // ---- chat surface (mirrors the workspace store) ----
    items: [], runs: {}, itemsLoading: false, canEdit: true, activeConvId: null, project: null,
    prefs: lsGet(LS_PREFS, DEFAULT_PREFS), models: [], uploads: [], draft: { text: '', nonce: 0 }, sending: false, sendError: null,
    usage: null, agents: [], conversations: [], draftAgent: null, tree: null,
    // ---- nexus ----
    ready: false, convLoading: false, scope: null, nexusRuns: {}, handoffRuns: {}, undoing: {},

    set: ((k: string, v: unknown) => set({ [k]: v } as Partial<NexusState>)) as typeof ws.set,
    setRightTab: () => {},
    setLeadAgent: async () => {},
    openFile: (p: string) => {
      const m = projectOfPath(p);
      if (m) window.open(`/p/${m.slug}`, '_blank', 'noopener');
    },

    async init() {
      if (get().ready) { get().loadScope(); get().loadConversations(); return; }
      set({ ready: true });
      api.get<any>('/models').then((m) => {
        const models = unwrap<ModelInfo[]>(m, 'models', 'items');
        if (!Array.isArray(models)) return;
        set({ models });
        if (models.length && !models.some((x) => x.id === get().prefs.model)) get().setPrefs({ model: models.find((x) => x.id === 'sonnet')?.id ?? models[0].id });
      }).catch(() => set({ models: [{ id: 'sonnet', label: 'Sonnet' }, { id: 'haiku', label: 'Haiku' }, { id: 'opus', label: 'Opus' }] }));
      get().refreshUsage();
      await Promise.all([get().loadScope(), get().loadConversations()]);
      const last = (() => { try { return localStorage.getItem(LS_CONV); } catch { return null; } })();
      const pick = get().conversations.find((c) => c.id === last);
      if (pick) await get().selectConversation(pick.id);
    },

    async loadScope() {
      try { set({ scope: await api.get<NexusScope>('/nexus/scope') }); } catch { /* optional */ }
    },

    async loadConversations() {
      set({ convLoading: !get().conversations.length });
      try {
        const list = unwrap<Conversation[]>(await api.get<any>('/nexus/conversations'), 'conversations', 'items');
        set({ conversations: list, convLoading: false });
      } catch { set({ convLoading: false }); }
    },

    async selectConversation(id) {
      const prev = get().activeConvId;
      if (prev && prev !== id) get().items.forEach((it) => it.runId && isTerminal(get().runs[it.runId]?.status) && dropSub(it.runId));
      set({ activeConvId: id, items: [], sendError: null });
      try { if (id) localStorage.setItem(LS_CONV, id); else localStorage.removeItem(LS_CONV); } catch { /* */ }
      if (id) await get().loadMessages(id);
    },

    newConversation() {
      get().selectConversation(null);
      get().setDraft('');
    },

    async renameConversation(id, title) {
      set((s) => ({ conversations: s.conversations.map((c) => (c.id === id ? { ...c, title } : c)) }));
      try { await api.patch(`/conversations/${id}`, { title }); } catch { get().loadConversations(); }
    },

    async deleteConversation(id) {
      set((s) => ({ conversations: s.conversations.filter((c) => c.id !== id) }));
      if (get().activeConvId === id) await get().selectConversation(null);
      try { await api.del(`/conversations/${id}`); } catch { get().loadConversations(); }
    },

    async loadMessages(convId, silent) {
      if (!silent) set({ itemsLoading: true });
      try {
        const msgs = unwrap<Message[]>(await api.get<any>(`/conversations/${convId}/messages`), 'messages', 'items');
        if (get().activeConvId !== convId) return;
        const items = toItems(msgs);
        const runs = { ...get().runs };
        const nexusRuns = { ...get().nexusRuns };
        const handoffRuns = { ...get().handoffRuns };
        for (const m of msgs) {
          if (!m.runId || m.role !== 'assistant') continue;
          const evs = (m.events || []) as StoredEvent[];
          const existing = runs[m.runId];
          const maxSeq = evs.reduce((a, e) => Math.max(a, e.seq), -1);
          let rv: RunView;
          if (existing && existing.lastSeq >= maxSeq) rv = existing;
          else {
            const startedAt = m.run?.startedAt ? Date.parse(m.run.startedAt) : undefined;
            rv = replay(m.runId, evs.map((e) => ({ type: e.type, data: e.data, seq: e.seq, ts: (e as any).ts }) as SeqEvent), emptyRun(m.runId, 'running', startedAt));
          }
          if (m.run) {
            if (m.run.status && (isTerminal(m.run.status) || !isTerminal(rv.status))) rv = setStatus(rv, m.run.status, m.run.endedAt ? Date.parse(m.run.endedAt) : undefined);
            if (m.run.startedAt && !rv.startedAt) rv = { ...rv, startedAt: Date.parse(m.run.startedAt) };
            if (!rv.model && m.run.model) rv = { ...rv, model: m.run.model };
          }
          if (m.suggestions?.length) rv = { ...rv, suggestions: m.suggestions };
          runs[m.runId] = rv;
          nexusRuns[m.runId] = {
            commits: m.nexusCommits ?? [], handoffs: m.handoffs ?? [],
            checkpointed: m.run?.nexus?.checkpointed ?? isTerminal(rv.status), focus: m.run?.nexus?.focus ?? [],
          };
          (m.handoffs ?? []).forEach((h, i) => {
            const k = `${m.runId}:${i}`;
            if (h.sent && !handoffRuns[k]) handoffRuns[k] = { runId: h.sent.runId, projectId: h.sent.projectId, slug: h.project, conversationId: h.sent.conversationId, status: 'done' };
          });
          if (!isTerminal(rv.status)) ensureSub(m.runId, rv.lastSeq + 1);
        }
        for (const it of items) if (it.runId && !runs[it.runId]) {
          const st = it.run?.status ?? 'queued';
          runs[it.runId] = emptyRun(it.runId, st, it.run?.startedAt ? Date.parse(it.run.startedAt) : undefined);
          if (!isTerminal(st)) ensureSub(it.runId, 0);
        }
        set({ items, runs, nexusRuns, handoffRuns, itemsLoading: false });
        // refresh the status of handoff runs we only know as "sent"
        for (const [k, h] of Object.entries(handoffRuns)) {
          if (h.status !== 'done') continue;
          api.get<{ status: RunStatus }>(`/runs/${h.runId}`).then((r) => set((s) => ({ handoffRuns: { ...s.handoffRuns, [k]: { ...s.handoffRuns[k], status: r.status } } }))).catch(() => {});
        }
      } catch (e) {
        set({ itemsLoading: false });
        if (!silent) set({ sendError: errInfo(e) });
      }
    },

    async send(text) {
      const s = get();
      if (s.sending) return false;
      const ups = s.uploads;
      if (ups.some((u) => u.status === 'uploading')) { set({ sendError: { code: 'uploading', message: 'Wait for uploads to finish.', status: 0 } }); return false; }
      const att = ups.filter((u) => u.status === 'done' && u.result);
      if (!text.trim() && !att.length) return false;
      set({ sending: true, sendError: null });
      try {
        let convId = s.activeConvId;
        if (!convId) {
          const conv = unwrap<Conversation>(await api.post<any>('/nexus/conversations', { model: s.prefs.model, mode: s.prefs.mode }), 'conversation');
          convId = conv.id;
          set((st) => ({ conversations: [conv, ...st.conversations.filter((c) => c.id !== conv.id)], activeConvId: conv.id, items: [] }));
          try { localStorage.setItem(LS_CONV, conv.id); } catch { /* */ }
        }
        const { prefs, scope } = get();
        const projects = parseMentions(text, scope?.projects ?? []);
        const res = await api.post<{ runId: string; messageId: string; conversation?: Conversation }>(`/conversations/${convId}/prompt`, {
          text, attachments: att.map((u) => u.result!.id), model: prefs.model, mode: prefs.mode, thinking: prefs.thinking, projects,
        });
        if (res.conversation?.id) set((st) => ({ conversations: st.conversations.map((c) => (c.id === res.conversation!.id ? { ...c, ...res.conversation } : c)) }));
        const now = new Date().toISOString();
        const runId = res.runId;
        set((st) => ({
          items: [
            ...st.items,
            { key: res.messageId || 'local:' + runId, id: res.messageId, role: 'user', content: text, attachments: att.map((u) => u.result!), createdAt: now, runId },
            { key: 'run:' + runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId,
              run: { id: runId, status: 'queued', model: prefs.model, mode: prefs.mode, startedAt: now, inputTokens: 0, outputTokens: 0, cacheRead: 0, cacheWrite: 0, costUsd: 0 } },
          ] as ChatItem[],
          runs: { ...st.runs, [runId]: st.runs[runId] ?? emptyRun(runId, 'queued', Date.now()) },
          nexusRuns: { ...st.nexusRuns, [runId]: { commits: [], handoffs: [], checkpointed: false, focus: projects } },
          uploads: [], sending: false,
        }));
        att.forEach((u) => u.previewUrl && URL.revokeObjectURL(u.previewUrl));
        ensureSub(runId, 0);
        return true;
      } catch (e) {
        set({ sending: false, sendError: errInfo(e) });
        return false;
      }
    },

    async abort(runId) {
      const id = runId ?? [...get().items].reverse().find((it) => it.runId && !isTerminal(get().runs[it.runId]?.status))?.runId;
      if (!id) return;
      try { await api.post(`/runs/${id}/abort`); } catch (e) { set({ sendError: errInfo(e) }); }
    },

    retry(runId) {
      const items = get().items;
      const idx = items.findIndex((i) => i.runId === runId && i.role === 'assistant');
      const user = [...items.slice(0, idx)].reverse().find((i) => i.role === 'user');
      if (user) get().send(user.content);
    },

    activeRunId() {
      const s = get();
      for (let i = s.items.length - 1; i >= 0; i--) { const r = s.items[i].runId && s.runs[s.items[i].runId!]; if (r && !isTerminal(r.status)) return r.runId; }
      return null;
    },

    handleServerMsg(msg) {
      const s = get();
      switch (msg.t) {
        case 'run_event': {
          if (!subscribed.has(msg.runId) && !s.runs[msg.runId]) return;
          const { t: _t, runId: _r, ...ev } = msg as any;
          putRun(msg.runId, (r) => applyRunEvent(r, ev as SeqEvent));
          const ctxTok = msg.type === 'compact' ? msg.data.postTokens
            : msg.type === 'usage' && !msg.data.parentId && msg.data.contextTokens ? msg.data.contextTokens : null;
          if (ctxTok != null && s.activeConvId && s.items.some((it) => it.runId === msg.runId))
            set((st) => ({ conversations: st.conversations.map((c) => (c.id === st.activeConvId ? { ...c, contextTokens: ctxTok } : c)) }));
          if (msg.type === 'done') { dropSub(msg.runId); scheduleReconcile(); }
          break;
        }
        case 'run_status': {
          if (msg.nexus && s.runs[msg.runId]) {
            putRun(msg.runId, (r) => (isTerminal(r.status) && !isTerminal(msg.status) ? r : setStatus(r, msg.status)));
            if (isTerminal(msg.status)) { dropSub(msg.runId); scheduleReconcile(); }
          } else if (!msg.nexus) {
            // a background handoff run finished / started
            const hit = Object.entries(s.handoffRuns).find(([, h]) => h.runId === msg.runId);
            if (hit) set((st) => ({ handoffRuns: { ...st.handoffRuns, [hit[0]]: { ...hit[1], status: msg.status } } }));
            if (isTerminal(msg.status)) window.setTimeout(() => get().loadScope(), 800);
          }
          break;
        }
        case 'suggestions':
          if (s.runs[msg.runId]) putRun(msg.runId, (r) => ({ ...r, suggestions: msg.items }));
          break;
        case 'nexus_run':
          set((st) => ({ nexusRuns: { ...st.nexusRuns, [msg.runId]: { focus: st.nexusRuns[msg.runId]?.focus ?? [], commits: msg.commits, handoffs: msg.handoffs, checkpointed: msg.checkpointed } } }));
          window.setTimeout(() => get().loadScope(), 300);
          break;
        case 'project_changed':
          if (msg.what === 'branches' || msg.what === 'project') window.setTimeout(() => get().loadScope(), 400);
          break;
      }
    },

    async sendHandoff(runId, idx) {
      const k = `${runId}:${idx}`;
      const h = get().nexusRuns[runId]?.handoffs[idx];
      if (!h || get().handoffRuns[k]) return;
      set((st) => ({ handoffRuns: { ...st.handoffRuns, [k]: { runId: '', projectId: '', slug: h.project, conversationId: '', status: 'sending' } } }));
      try {
        const r = await api.post<{ runId: string; projectId: string; projectSlug: string; conversation: Conversation; handoffs: NexusHandoff[] }>(`/runs/${runId}/handoffs/${idx}`, {});
        set((st) => ({
          handoffRuns: { ...st.handoffRuns, [k]: { runId: r.runId, projectId: r.projectId, slug: r.projectSlug, conversationId: r.conversation.id, status: 'queued' } },
          nexusRuns: { ...st.nexusRuns, [runId]: { ...st.nexusRuns[runId], handoffs: r.handoffs } },
        }));
      } catch (e) {
        set((st) => { const hr = { ...st.handoffRuns }; delete hr[k]; return { handoffRuns: hr, sendError: errInfo(e) }; });
      }
    },

    async undoRun(runId, projectId) {
      const k = `${runId}:${projectId ?? '*'}`;
      set((st) => ({ undoing: { ...st.undoing, [k]: true } }));
      try {
        const r = await api.post<{ ok: boolean; results: { projectId: string; slug: string; ok: boolean; conflicts?: string[]; error?: string }[] }>(
          projectId ? `/runs/${runId}/undo-nexus?project=${encodeURIComponent(projectId)}` : `/runs/${runId}/undo`,
        );
        const okIds = new Set(r.results.filter((x) => x.ok).map((x) => x.projectId));
        set((st) => ({ nexusRuns: { ...st.nexusRuns, [runId]: { ...st.nexusRuns[runId], commits: st.nexusRuns[runId].commits.map((c) => (okIds.has(c.projectId) ? { ...c, undone: true } : c)) } } }));
        const bad = r.results.filter((x) => !x.ok);
        if (bad.length) set({ sendError: { code: 'undo_failed', message: `Undo failed for ${bad.map((b) => `${b.slug}${b.conflicts?.length ? ' (conflicts)' : b.error ? ` (${b.error})` : ''}`).join(', ')}`, status: 409 } });
      } catch (e) { set({ sendError: errInfo(e) }); }
      finally { set((st) => { const u = { ...st.undoing }; delete u[k]; return { undoing: u }; }); }
    },

    setPrefs(p) {
      const prefs = { ...get().prefs, ...p };
      set({ prefs });
      try { localStorage.setItem(LS_PREFS, JSON.stringify(prefs)); } catch { /* */ }
    },
    setDraft(text) { set((s) => ({ draft: { text, nonce: s.draft.nonce + 1 } })); },
    addFiles(files) {
      for (const file of files) {
        const localId = Math.random().toString(36).slice(2);
        const isImg = file.type.startsWith('image/');
        const up: PendingUpload = { localId, file, name: file.name || 'pasted-file', size: file.size, mime: file.type, progress: 0, status: 'uploading', previewUrl: isImg ? URL.createObjectURL(file) : undefined };
        set((s) => ({ uploads: [...s.uploads, up] }));
        const form = new FormData();
        form.append('file', file, up.name);
        const patch = (p: Partial<PendingUpload>) => set((s) => ({ uploads: s.uploads.map((u) => (u.localId === localId ? { ...u, ...p } : u)) }));
        api.upload<Attachment>('/uploads', form, (f) => patch({ progress: f }))
          .then((r) => patch({ status: 'done', progress: 1, result: unwrap<Attachment>(r, 'upload') }))
          .catch((e) => patch({ status: 'error', error: errInfo(e).message }));
      }
    },
    removeUpload(localId) {
      set((s) => {
        const u = s.uploads.find((x) => x.localId === localId);
        if (u?.previewUrl) URL.revokeObjectURL(u.previewUrl);
        return { uploads: s.uploads.filter((x) => x.localId !== localId) };
      });
    },
    clearSendError() { set({ sendError: null as SendError | null }); },
    async refreshUsage() {
      try { set({ usage: await api.get<UsageSummary>('/usage/me') }); } catch { /* optional */ }
    },
    async compact(instructions) {
      const s = get();
      const convId = s.activeConvId;
      if (!convId) return false;
      set({ sendError: null });
      try {
        const res = await api.post<{ runId: string; messageId: string }>(`/conversations/${convId}/compact`, { instructions: instructions ?? '' });
        const now = new Date().toISOString();
        const content = `/compact${instructions?.trim() ? ' ' + instructions.trim() : ''}`;
        set((st) => ({
          items: [
            ...st.items,
            { key: res.messageId || 'local:' + res.runId, id: res.messageId, role: 'user', content, attachments: [], createdAt: now, runId: res.runId, kind: 'compact' },
            { key: 'run:' + res.runId, role: 'assistant', content: '', attachments: [], createdAt: now, runId: res.runId, kind: 'compact' },
          ] as ChatItem[],
          runs: { ...st.runs, [res.runId]: st.runs[res.runId] ?? emptyRun(res.runId, 'queued', Date.now()) },
        }));
        ensureSub(res.runId, 0);
        return true;
      } catch (e) { set({ sendError: errInfo(e) }); return false; }
    },
  };
  return store;
});

