// Nexus Chat dock: a handle at the bottom center of the Nexus that slides up a resizable glass panel
// (⌘J / "/" to open, Esc to collapse; full-screen sheet on phones). The chat body is lazy-loaded.
import { lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState, type RefObject } from 'react';
import clsx from 'clsx';
import { ChevronDown, Maximize2, Minimize2 } from 'lucide-react';
import { Kbd, LogoGlyph, modKey } from '@/components/ui';
import { live } from '@/lib/ws';
import { useUI } from '@/stores/ui';
import { isTerminal } from '../workspace/store';
import { useMediaQuery } from '../workspace/ui';
import type { NexusEngine } from './engine';
import { parseMentions } from './mentions';
import { useNexusChat } from './nexusStore';

const NexusChatBody = lazy(() => import('./NexusChatBody'));

const LS = 'nx.nexus.chat';
interface DockState { open: boolean; h: number; full: boolean }
const DEFAULT: DockState = { open: false, h: 0.45, full: false };
const load = (): DockState => { try { return { ...DEFAULT, ...JSON.parse(localStorage.getItem(LS) || '{}') }; } catch { return DEFAULT; } };
const save = (s: DockState) => { try { localStorage.setItem(LS, JSON.stringify(s)); } catch { /* */ } };

const focusPrompt = () => window.setTimeout(() => window.dispatchEvent(new Event('nxw:focus-prompt')), 60);

export function NexusChat({ engine }: { engine: RefObject<NexusEngine | null> }) {
  const [st, setSt] = useState<DockState>(load);
  const [dragH, setDragH] = useState<number | null>(null);
  const [loaded, setLoaded] = useState(st.open);
  const [unseen, setUnseen] = useState(false);
  const mobile = useMediaQuery('(max-width: 639px)');
  const hostRef = useRef<HTMLDivElement>(null);
  const update = useCallback((p: Partial<DockState>) => setSt((s) => { const n = { ...s, ...p }; save(n); return n; }), []);
  const open = (o: boolean) => { update({ open: o }); if (o) { setLoaded(true); setUnseen(false); focusPrompt(); } };

  // live: route socket messages into the Nexus store (it ignores what isn't its own)
  useEffect(() => {
    live.connect();
    useNexusChat.getState().init();
    return live.on((m) => useNexusChat.getState().handleServerMsg(m));
  }, []);

  // running / finished state for the dock + the core animation
  const runningId = useNexusChat((s) => {
    for (let i = s.items.length - 1; i >= 0; i--) { const r = s.items[i].runId && s.runs[s.items[i].runId!]; if (r && !isTerminal(r.status)) return r.runId; }
    return null;
  });
  const wasRunning = useRef<string | null>(null);
  useEffect(() => {
    engine.current?.setNexusActive(!!runningId);
    if (wasRunning.current && !runningId && !st.open) setUnseen(true);
    wasRunning.current = runningId;
  }, [runningId, engine, st.open]);

  // highlight #mentioned projects while typing, and the focus/touched projects of the active run
  const scope = useNexusChat((s) => s.scope);
  const [typed, setTyped] = useState<string[]>([]);
  const activeFocus = useNexusChat((s) => (runningId ? s.nexusRuns[runningId]?.focus ?? [] : []));
  const touched = useNexusChat((s) => (runningId ? s.runs[runningId]?.touched ?? [] : []));
  const highlight = useMemo(() => {
    const bySlug = new Map((scope?.projects ?? []).map((p) => [p.slug, p.id]));
    const ids = new Set<string>();
    for (const f of [...typed, ...activeFocus]) { const id = bySlug.get(f.split('@')[0]); if (id) ids.add(id); }
    for (const t of touched) ids.add(t);
    return [...ids];
  }, [typed, activeFocus, touched, scope]);
  useEffect(() => { engine.current?.setHighlight(st.open || runningId ? highlight : []); }, [highlight, st.open, runningId, engine]);
  useEffect(() => () => { engine.current?.setHighlight([]); engine.current?.setNexusActive(false); }, [engine]);
  const onText = useCallback((text: string) => {
    const next = text.includes('#') ? parseMentions(text, useNexusChat.getState().scope?.projects ?? []) : [];
    setTyped((cur) => (cur.join(',') === next.join(',') ? cur : next));
  }, []);

  // keyboard: ⌘J toggles, "/" opens, Esc collapses
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement;
      const typing = el?.tagName === 'INPUT' || el?.tagName === 'TEXTAREA' || el?.isContentEditable;
      const ui = useUI.getState();
      if ((e.metaKey || e.ctrlKey) && !e.altKey && e.key.toLowerCase() === 'j') {
        e.preventDefault();
        setSt((s) => { const n = { ...s, open: !s.open }; save(n); if (n.open) { setLoaded(true); setUnseen(false); focusPrompt(); } return n; });
        return;
      }
      if (ui.paletteOpen || ui.newProjectOpen || document.querySelector('[role=dialog]')) return;
      if (e.key === '/' && !typing && !e.metaKey && !e.ctrlKey && !e.altKey) {
        e.preventDefault();
        open(true);
        return;
      }
      if (e.key === 'Escape' && !e.defaultPrevented && st.open && !document.querySelector('.nxw-pop')) {
        if (typing && !hostRef.current?.contains(el)) return;
        e.preventDefault();
        (el as HTMLElement)?.blur?.();
        open(false);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }); // eslint-disable-line react-hooks/exhaustive-deps

  // resize by dragging the top edge (double-click toggles full height)
  const onGrab = (e: React.PointerEvent) => {
    if (mobile) return;
    e.preventDefault();
    const host = hostRef.current?.parentElement; if (!host) return;
    const r = host.getBoundingClientRect();
    const move = (ev: PointerEvent) => setDragH(Math.min(1, Math.max(0.22, (r.bottom - ev.clientY) / r.height)));
    const up = (ev: PointerEvent) => {
      window.removeEventListener('pointermove', move); window.removeEventListener('pointerup', up);
      const h = Math.min(1, Math.max(0.22, (r.bottom - ev.clientY) / r.height));
      setDragH(null);
      if (h > 0.93) update({ full: true }); else update({ h, full: false });
    };
    window.addEventListener('pointermove', move); window.addEventListener('pointerup', up);
  };

  const height = dragH != null ? `${dragH * 100}%` : st.full ? 'calc(100% - 20px)' : `${st.h * 100}%`;
  const n = scope?.projects.length ?? 0;

  return (
    <div ref={hostRef} className="pointer-events-none absolute inset-0 z-20" data-testid="nexus-chat">
      {/* dock handle */}
      <button
        type="button" onClick={() => open(true)} data-testid="nexus-chat-handle"
        className={clsx(
          'nx-glass pointer-events-auto absolute bottom-4 left-1/2 flex -translate-x-1/2 items-center gap-2.5 rounded-full py-1.5 pl-2 pr-2.5 text-[12.5px] text-ink/90 transition-all duration-300 hover:border-pink/50 hover:text-ink hover:shadow-[0_0_30px_-6px_rgba(255,62,138,.6)]',
          st.open ? 'pointer-events-none translate-y-6 opacity-0' : 'translate-y-0 opacity-100',
        )}
        aria-label="Open Nexus Chat"
      >
        <span className="relative flex h-6 w-6 items-center justify-center">
          <LogoGlyph size={20} className={clsx(runningId && 'animate-[spin_6s_linear_infinite]')} />
          {(runningId || unseen) && <span className={clsx('absolute -right-0.5 -top-0.5 h-2 w-2 rounded-full', runningId ? 'animate-pulse bg-hot shadow-[0_0_8px_#ff6fae]' : 'bg-ok shadow-[0_0_8px_#3dffb5]')} />}
        </span>
        <span className="font-display text-[10.5px] font-semibold tracking-[0.22em]">NEXUS CHAT</span>
        {n > 0 && <span className="hidden font-mono text-[10.5px] text-muted sm:inline">{n} project{n === 1 ? '' : 's'}</span>}
        <Kbd className="hidden sm:inline-flex">{modKey}J</Kbd>
      </button>

      {/* panel */}
      <section
        aria-label="Nexus Chat" aria-hidden={!st.open}
        className={clsx(
          'pointer-events-auto absolute flex flex-col overflow-hidden transition-[transform,opacity] duration-300 ease-out',
          mobile ? 'inset-0 rounded-none' : 'bottom-3 left-1/2 w-[min(1040px,calc(100%-24px))] -translate-x-1/2 rounded-2xl',
          'nx-glass !bg-[linear-gradient(180deg,rgba(22,14,26,.88),rgba(15,10,18,.94))]',
          st.open ? 'translate-y-0 opacity-100' : 'pointer-events-none translate-y-[calc(100%+24px)] opacity-0',
          dragH != null && '!transition-none',
        )}
        style={mobile ? undefined : { height }}
      >
        <div className="absolute inset-x-10 -top-px h-px bg-gradient-to-r from-transparent via-pink/70 to-transparent" />
        {!mobile && (
          <div onPointerDown={onGrab} onDoubleClick={() => update({ full: !st.full })} title="Drag to resize · double-click to maximize"
            className="group absolute inset-x-0 top-0 z-10 flex h-3 cursor-ns-resize justify-center">
            <span className="mt-1 h-1 w-10 rounded-full bg-white/10 transition group-hover:bg-pink/50" />
          </div>
        )}
        {loaded && (
          <Suspense fallback={<div className="flex flex-1 items-center justify-center text-xs text-muted">Loading…</div>}>
            <NexusChatBody
              onTextChange={onText}
              headerActions={
                <>
                  {!mobile && (
                    <button type="button" onClick={() => update({ full: !st.full })} aria-label={st.full ? 'Restore size' : 'Maximize'} title={st.full ? 'Restore size' : 'Maximize'}
                      className="flex h-7 w-7 items-center justify-center rounded-md text-muted transition hover:bg-white/5 hover:text-ink">
                      {st.full ? <Minimize2 size={14} /> : <Maximize2 size={14} />}
                    </button>
                  )}
                  <button type="button" onClick={() => open(false)} aria-label="Collapse (Esc)" title="Collapse (Esc)" data-testid="nexus-chat-collapse"
                    className="flex h-7 w-7 items-center justify-center rounded-md text-muted transition hover:bg-white/5 hover:text-ink">
                    <ChevronDown size={16} />
                  </button>
                </>
              }
            />
          </Suspense>
        )}
      </section>
    </div>
  );
}

