                  <button type="button" onClick={() => open(false)} aria-label="Collapse (Esc)" title="Collapse (Esc)" data-testid="nexus-chat-collapse"
                    className="flex h-7 w-7 items-center justify-center rounded-md text-muted transition hover:bg-white/5 hover:text-ink">
                    <ChevronDown size={16} />
                  </button>
                </>
              }
            />
          </Suspense>
        )}
      </section>
    </div>
  );
}

