          <div className="flex items-center gap-2 border-b border-line/60 px-3 py-1.5 text-[11px] uppercase tracking-[.14em] text-muted">
            <Layers size={12} className="text-pink/80" /> Changed {commits.length} project{commits.length === 1 ? '' : 's'}
            {open.length > 1 && (
              <button type="button" onClick={() => undoRun(runId)} disabled={!!undoing[`${runId}:*`]} data-testid="nexus-undo-all"
                className="ml-auto inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 normal-case tracking-normal text-muted transition hover:bg-white/5 hover:text-ink disabled:opacity-50">
                {undoing[`${runId}:*`] ? <Spin className="h-3 w-3" /> : <Undo2 size={12} />} Undo all
              </button>
            )}
          </div>
          <ul className="divide-y divide-line/50">
            {commits.map((c) => (
              <li key={`${c.projectId}|${c.branch ?? ''}`} className={clsx('flex items-center gap-2 px-3 py-1.5 text-[12.5px]', c.undone && 'opacity-55')}>
                <Chip slug={c.slug} branch={c.branch} color={c.color} />
                <span className={clsx('text-muted', c.undone && 'line-through')}>{c.files} file{c.files === 1 ? '' : 's'} changed</span>
                <span className="ml-auto flex items-center gap-1">
                  <Tip label={`Open ${c.name}`}>
                    <Link to={`/p/${c.slug}${c.branch ? `?branch=${encodeURIComponent(c.branch)}` : ''}`} className="flex h-6 w-6 items-center justify-center rounded-md text-muted hover:bg-white/5 hover:text-ink"><ArrowUpRight size={13} /></Link>
                  </Tip>
                  {c.undone ? <span className="px-1.5 text-[11px] text-muted">undone</span> : (
                    <button type="button" onClick={() => undoRun(runId, c.projectId)} disabled={!!undoing[`${runId}:${c.projectId}`] || !!undoing[`${runId}:*`]}
                      className="inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[11.5px] text-muted transition hover:bg-white/5 hover:text-ink disabled:opacity-50">
                      {undoing[`${runId}:${c.projectId}`] ? <Spin className="h-3 w-3" /> : <Undo2 size={12} />} Undo
                    </button>
                  )}
                </span>
              </li>
            ))}
          </ul>
        </div>
      )}
      {!live && info?.handoffs && info.handoffs.length > 0 && (
        <div className="space-y-1.5" data-testid="nexus-handoffs">
          <div className="flex items-center gap-1.5 text-[11px] uppercase tracking-[.14em] text-muted"><CornerDownRight size={12} className="text-warm" /> Suggested handoffs</div>
          {info.handoffs.map((h, i) => {
            const hr = handoffRuns[`${runId}:${i}`];
            const p = scope?.projects.find((x) => x.slug === h.project);
            return (
              <div key={i} className="flex items-start gap-2.5 rounded-xl border border-line/80 bg-panel2/40 px-3 py-2">
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5"><Chip slug={h.project} branch={h.branch} color={p?.color} /></div>
                  <Tip label={<span className="whitespace-pre-wrap">{h.prompt.slice(0, 600)}</span>}>
                    <p className="mt-1 line-clamp-2 text-[12.5px] leading-snug text-ink/75">{h.prompt}</p>
                  </Tip>
                </div>
                {hr && hr.status !== 'sending' ? (
                  <Link to={`/p/${hr.slug}?conv=${encodeURIComponent(hr.conversationId)}${h.branch ? `&branch=${encodeURIComponent(h.branch)}` : ''}`} data-testid="nexus-handoff-chip"
                    className="inline-flex shrink-0 items-center gap-1.5 self-center rounded-full border border-line bg-bg/60 px-2.5 py-1 text-[12px] text-ink/90 transition hover:border-pink/50">
                    {isTerminal(hr.status as never) ? (hr.status === 'done' ? <Check size={12} className="text-ok" /> : <TriangleAlert size={12} className="text-bad" />) : <Spin className="h-3 w-3" />}
                    {isTerminal(hr.status as never) ? (hr.status === 'done' ? 'Done' : hr.status) : 'Running'} in {hr.slug}
                    <ArrowUpRight size={12} className="text-muted" />
                  </Link>
                ) : (
                  <button type="button" onClick={() => sendHandoff(runId, i)} disabled={!!hr || !p} data-testid="nexus-handoff-send"
                    title={p ? 'Starts a new conversation in that project and runs it in the background' : 'Project not in your scope anymore'}
                    className="inline-flex shrink-0 items-center gap-1.5 self-center rounded-full border border-pink/40 bg-pink/10 px-3 py-1 text-[12px] text-hot transition hover:bg-pink/20 hover:shadow-[0_0_16px_-4px_rgba(255,62,138,.7)] disabled:opacity-50">
                    {hr ? <Spin className="h-3 w-3" /> : <Send size={12} />} Send to {h.project}
                  </button>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function EmptyNexus() {
  const scope = useNexusChat((s) => s.scope);
  const setDraft = useNexusChat((s) => s.setDraft);
  const ps = scope?.projects ?? [];
  const a = ps[0]?.slug, b = ps[1]?.slug;
  const starters = [
    { label: 'One-line status of every project', prompt: 'Give me a one-line status of every project (what it is, what state it is in). Read only README files; no edits.' },
    a && b ? { label: `Compare #${a} and #${b}`, prompt: `Compare #${a} and #${b}: structure, styling and README. List inconsistencies; don't edit anything yet.` } : null,
    a ? { label: `Small fix across projects`, prompt: `In #${a}${b ? ` and #${b}` : ''}, ` } : null,
  ].filter(Boolean) as { label: string; prompt: string }[];
  return (
    <div className="flex min-h-[240px] flex-col items-center justify-center px-6 py-8 text-center">
      <div className="relative mb-4">
        <div className="absolute inset-0 rounded-full bg-pink/25 blur-2xl" />
        <LogoGlyph size={40} className="relative" />
      </div>
      <h2 className="font-display text-[13px] tracking-[.22em] text-ink">NEXUS CHAT</h2>
      <p className="mt-2 max-w-md text-[13px] leading-relaxed text-muted">
        One chat across {ps.length ? <span className="text-ink/90">{ps.length} project{ps.length === 1 ? '' : 's'}</span> : 'your projects'}.
        Type <span className="rounded bg-white/5 px-1 font-mono text-hot">#</span> to focus projects — runs stay cheaper and more precise.
        {scope?.viewOnly ? <span className="block text-[11.5px] text-muted/70">{scope.viewOnly} view-only project{scope.viewOnly === 1 ? ' is' : 's are'} not included.</span> : null}
      </p>
      {starters.length > 0 && (
        <div className="mt-5 flex flex-wrap justify-center gap-2">
          {starters.map((s) => (
            <button key={s.label} type="button" onClick={() => setDraft(s.prompt)}
              className="rounded-full border border-line bg-panel/60 px-3 py-1.5 text-[12.5px] text-ink/85 transition hover:-translate-y-px hover:border-pink/40 hover:bg-pink/[.06]">
              {s.label}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function ConversationSwitcher() {
  const convs = useNexusChat((s) => s.conversations);
  const activeId = useNexusChat((s) => s.activeConvId);
  const runs = useNexusChat((s) => s.runs);
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const [open, setOpen] = useState(false);
  const [renaming, setRenaming] = useState<string | null>(null);
  const { selectConversation, newConversation, deleteConversation, renameConversation } = useNexusChat.getState();
  const active = convs.find((c) => c.id === activeId);
  const running = Object.values(runs).some((r) => !isTerminal(r.status));
  return (
    <>
      <button ref={setAnchor} type="button" onClick={() => setOpen(!open)} data-testid="nexus-conv-switcher"
        className="flex min-w-0 items-center gap-1.5 rounded-lg px-2 py-1 text-[13px] text-ink/90 transition hover:bg-white/5">
        <MessagesSquare size={14} className="shrink-0 text-muted" />
        <span className="truncate">{active?.title ?? 'New chat'}</span>
        {running && <span className="h-1.5 w-1.5 shrink-0 animate-pulse rounded-full bg-hot" />}
        <ChevronDown size={13} className="shrink-0 text-muted" />
      </button>
      <Popover open={open} anchor={anchor} onClose={() => { setOpen(false); setRenaming(null); }} side="bottom" className="w-[320px]">
        <button type="button" onClick={() => { newConversation(); setOpen(false); window.dispatchEvent(new Event('nxw:focus-prompt')); }}
          className="flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left text-[13px] text-ink hover:bg-white/5">
          <Plus size={14} className="text-hot" /> New chat
        </button>
        {convs.length > 0 && <div className="my-1 h-px bg-line" />}
        <div className="nxw-scroll max-h-[300px] overflow-y-auto">
          {convs.map((c) => (
            <div key={c.id} className={clsx('group flex items-center gap-1 rounded-lg pr-1', c.id === activeId ? 'bg-pink/10' : 'hover:bg-white/5')}>
              {renaming === c.id ? (
                <InlineInput initial={c.title} className="m-1 flex-1" onCancel={() => setRenaming(null)} onCommit={(t) => { setRenaming(null); if (t.trim()) renameConversation(c.id, t.trim()); }} />
              ) : (
                <button type="button" onClick={() => { selectConversation(c.id); setOpen(false); }} className="flex min-w-0 flex-1 items-baseline gap-2 px-2.5 py-1.5 text-left">
                  <span className={clsx('truncate text-[13px]', c.id === activeId ? 'text-ink' : 'text-ink/80')}>{c.title}</span>
                  <span className="ml-auto shrink-0 font-mono text-[10.5px] text-muted">{timeAgo(c.updatedAt)}</span>
                </button>
              )}
              {renaming !== c.id && (
                <span className="flex opacity-0 transition group-hover:opacity-100">
                  <button type="button" aria-label="Rename" onClick={() => setRenaming(c.id)} className="flex h-6 w-6 items-center justify-center rounded text-muted hover:text-ink"><Pencil size={12} /></button>
                  <button type="button" aria-label="Delete" onClick={() => { if (window.confirm(`Delete "${c.title}"?`)) deleteConversation(c.id); }} className="flex h-6 w-6 items-center justify-center rounded text-muted hover:text-bad"><Trash2 size={12} /></button>
                </span>
              )}
            </div>
          ))}
        </div>
      </Popover>
    </>
  );
}

function ScopePill() {
  const scope = useNexusChat((s) => s.scope);
  const n = scope?.projects.length ?? 0;
  if (!scope) return null;
  return (
    <Tip label={
      <span className="block max-w-[260px]">
        <span className="mb-1 block text-muted">Claude can read & edit these projects (edit access):</span>
        {scope.projects.slice(0, 24).map((p) => <span key={p.id} className="mr-1.5 inline-flex items-center gap-1 font-mono text-[11px]"><span className="h-1.5 w-1.5 rounded-full" style={{ background: p.color }} />{p.slug}</span>)}
        {n > 24 && <span className="text-muted"> +{n - 24}</span>}
        {scope.viewOnly ? <span className="mt-1 block text-muted">{scope.viewOnly} view-only excluded</span> : null}
      </span>
    }>
      <span className="hidden items-center gap-1 rounded-md px-1.5 py-0.5 text-[11.5px] text-muted sm:flex" data-testid="nexus-scope">
        <Layers size={12} /> {n} project{n === 1 ? '' : 's'} in scope
      </span>
    </Tip>
  );
}

export default function NexusChatBody({ onTextChange, headerActions }: { onTextChange: (t: string) => void; headerActions: ReactNode }) {
  const scope = useNexusChat((s) => s.scope);
  const mentions: MentionOption[] = useMemo(
    () => (scope?.projects ?? []).map((p) => ({ slug: p.slug, name: p.name, color: p.color, branches: p.branches, description: p.description, busy: p.busy })),
    [scope],
  );
  const ctx: ChatContextValue = useMemo(() => ({
    store: useNexusChat as unknown as ChatStoreHook,
    compact: true,
    emptyState: <EmptyNexus />,
    renderRunExtras: (runId, live) => <RunExtras runId={runId} live={live} />,
    prompt: {
      mentions,
      onTextChange,
      placeholder: 'Ask across your projects…  ( # focus a project · / commands )',
      hideAgent: true,
      hideCommands: ['preview', 'files'],
      footerInfo: <ScopePill />,
      notice: (text: string) => {
        const n = mentions.length;
        if (n <= WARN_PROJECTS || !text.trim() || text.startsWith('/') || parseMentions(text, mentions).length) return null;
        return (
          <div className="nxw-fade-in mb-1.5 flex items-center gap-2 px-1 text-[12px] text-warn/85" data-testid="nexus-focus-hint">
            <GitBranch size={12} className="shrink-0 rotate-90" />
            No <span className="font-mono">#focus</span> — Claude gets an index of all {n} projects. Mention the ones you mean to keep the run lean.
          </div>
        );
      },
    },
  }), [mentions, onTextChange]);

  return (
    <ChatCtx.Provider value={ctx}>
      <header className="relative flex h-11 shrink-0 items-center gap-2 border-b border-line/60 px-3 pt-1">
        <LogoGlyph size={18} />
        <span className="hidden font-display text-[10.5px] font-semibold tracking-[0.24em] text-ink/90 sm:inline">NEXUS CHAT</span>
        <span className="hidden text-muted/40 sm:inline">/</span>
        <div className="min-w-0 flex-1"><ConversationSwitcher /></div>
        <Tip label="New chat"><button type="button" aria-label="New chat" onClick={() => { useNexusChat.getState().newConversation(); window.dispatchEvent(new Event('nxw:focus-prompt')); }}
          className="flex h-7 w-7 items-center justify-center rounded-md text-muted transition hover:bg-white/5 hover:text-ink"><Plus size={15} /></button></Tip>
        {headerActions}
      </header>
      <div className="min-h-0 flex-1"><Chat /></div>
    </ChatCtx.Provider>
  );
}

