import { chromium } from 'playwright';
import fs from 'node:fs';
export const BASE = 'https://workspace.trynxeon.com';
const env = Object.fromEntries(fs.readFileSync('/opt/nxeon-workspace/.env', 'utf8').split('\n').filter((l) => l.includes('=') && !l.startsWith('#')).map((l) => [l.slice(0, l.indexOf('=')), l.slice(l.indexOf('=') + 1)]));
export const ADMIN = { email: env.ADMIN_EMAIL, password: env.ADMIN_PASSWORD };
export const problems = [];
export async function launch(extra = []) {
  return chromium.launch({ channel: process.env.CH || undefined,
    args: ['--host-resolver-rules=MAP workspace.trynxeon.com 127.0.0.1', '--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream', ...extra],
  });
}
export async function newPage(browser, opts = {}, tag = 'main') {
  const ctx = await browser.newContext({ viewport: { width: 1600, height: 960 }, permissions: ['microphone', 'clipboard-read', 'clipboard-write'], ...opts });
  const page = await ctx.newPage();
  page.on('pageerror', (e) => { const s = `[${tag}] PAGEERROR ${e.message}`; problems.push(s); console.log(s); });
  page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') { const s = `[${tag}] console.${m.type()} ${m.text().slice(0, 400)}`; problems.push(s); console.log(s); } });
  page.on('request', (r) => { const u = new URL(r.url()); if (!['workspace.trynxeon.com'].includes(u.hostname) && !['data:', 'blob:'].includes(u.protocol)) { const s = `[${tag}] EXTERNAL ${r.url()}`; problems.push(s); console.log(s); } });
  page.on('response', (r) => { if (r.status() >= 400) { const s = `[${tag}] HTTP ${r.status()} ${r.request().method()} ${r.url().replace(BASE, '')}`; console.log(s); } });
  return page;
}
export async function shot(page, name) { await page.screenshot({ path: `shots/${name}.png` }); console.log('shot', name); }
export async function login(page, email = ADMIN.email, password = ADMIN.password) {
  await page.goto(BASE + '/login', { waitUntil: 'networkidle' });
  await page.locator('input[type=email], input[name=email], input[autocomplete=username]').first().fill(email);
  await page.locator('input[type=password]').first().fill(password);
  await page.keyboard.press('Enter');
}
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
import { launch, newPage, BASE, sleep } from './lib.mjs';
for (const extra of [[], ['--no-sandbox','--use-file-for-fake-audio-capture=' + process.cwd() + '/en48.wav']]) {
const b = await launch(extra);
const p = await newPage(b);
await p.goto(BASE + '/login');
const r = await p.evaluate(async () => {
  const s = await navigator.mediaDevices.getUserMedia({ audio: true });
  const ctx = new AudioContext(); await ctx.resume(); const an = ctx.createAnalyser(); ctx.createMediaStreamSource(s).connect(an);
  const buf = new Float32Array(2048); let max = 0;
  for (let i = 0; i < 20; i++) { await new Promise((r) => setTimeout(r, 100)); an.getFloatTimeDomainData(buf); for (const v of buf) max = Math.max(max, Math.abs(v)); }
  return { label: s.getAudioTracks()[0].label, settings: s.getAudioTracks()[0].getSettings(), max, ctxState: ctx.state };
});
console.log(extra.length, JSON.stringify(r));
await b.close();
}
import { launch, newPage, shot, login, ADMIN, BASE, sleep, problems } from './lib.mjs';
const b = await launch();
const p = await newPage(b);
await p.goto(BASE + '/', { waitUntil: 'networkidle' });
console.log('url after / unauth', p.url());
await sleep(1500); await shot(p, '01-login');
await login(p, ADMIN.email, 'wrong-password-123');
await sleep(1500); await shot(p, '02-login-bad');
console.log('bad login text:', (await p.locator('form').innerText()).slice(0, 300));
await login(p);
await p.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 10000 });
await sleep(3000); await shot(p, '03-nexus');
console.log('nexus url', p.url());
// palette
await p.keyboard.press('Control+k'); await sleep(600); await shot(p, '04-palette');
console.log('palette text:', (await p.locator('[role=dialog]').first().innerText().catch(() => 'NO DIALOG')).slice(0, 400));
await p.keyboard.press('Escape');

