import { launch, newPage, login, BASE, sleep, problems } from '../lib.mjs';
import { req, login as apiLogin } from './api.mjs';
const shot = async (p, n) => { await p.screenshot({ path: `shots/${n}.png` }); console.log('shot', n); };
const c = await apiLogin();
const conv = (await req('GET', '/nexus/conversations', undefined, c)).json[0];
const b = await launch();
const p = await newPage(b);
await login(p);
await p.waitForURL((u) => !u.pathname.startsWith('/login'), { timeout: 15000 });
await p.evaluate((id) => {
  localStorage.setItem('nx:nexus:prefs', JSON.stringify({ model: 'haiku', mode: 'auto', thinking: 'off' }));
  localStorage.setItem('nx:nexus:conv', id);
  localStorage.setItem('nx.nexus.chat', JSON.stringify({ open: true, h: 0.55, full: false }));
}, conv.id);
await p.goto(BASE + '/', { waitUntil: 'networkidle' }); await sleep(2500);
await p.locator('[data-testid=nexus-handoff-send]').first().click();
await sleep(2500);
await shot(p, '08-handoff-running-chip');
for (let i = 0; i < 60; i++) { if (await p.locator('[data-testid=nexus-handoff-chip]', { hasText: 'Done' }).count()) break; await sleep(2000); }
await sleep(1000);
await shot(p, '09-handoff-done-chip');
// undo all (per-project checkpoints of the nexus run)
await p.locator('[data-testid=nexus-undo-all]').click();
await sleep(3000);
await shot(p, '10-undo-all');
// mobile
const m = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true, storageState: await p.context().storageState() });
const mp = await m.newPage();
await mp.goto(BASE + '/'); await mp.evaluate(() => localStorage.setItem('nx.nexus.chat', JSON.stringify({ open: false, h: 0.45, full: false })));
await mp.goto(BASE + '/'); await sleep(2500);
await mp.screenshot({ path: 'shots/11-mobile-390-collapsed.png' });
await mp.locator('[data-testid=nexus-chat-handle]').click(); await sleep(2000);
await mp.screenshot({ path: 'shots/12-mobile-390-sheet.png' });
console.log('PROBLEMS', problems.filter((x) => !/401/.test(x)));
await b.close();
EOF
timeout 240 node live-run3.mjs 2>&1 | grep -v 401

